const MODE_NAME: Record<string, string> = { streetcar: 'streetcar', lightrail: 'light rail', cablecar: 'cable car', bart: 'BART', caltrain: 'Caltrain', ferry: 'ferry' };
const PURPOSE_NAME: Record<string, string> = { work: 'Commute', school: 'School (K–12)', univ: 'College', shop: 'Shopping', other: 'Errands and other', social: 'Social, dining, and recreation' };
/** the periods each leg of a tour travels in (the weights mode choice mixes the periods' service by) */
const LEG_SHARES = Object.fromEntries(
  (['work', 'social'] as const).map((p) => {
    const w = legWeights(TOD[p], false);
    const by = (a: Float64Array) => Object.fromEntries(TPERIODS.map((t, k) => [t, a[k]])) as Record<(typeof TPERIODS)[number], number>;
    return [p, { out: by(w.out), back: by(w.back) }];
  }),
) as Record<'work' | 'social', { out: Record<(typeof TPERIODS)[number], number>; back: Record<(typeof TPERIODS)[number], number> }>;
const CAPACITY_FERRY = '600 a sailing to Larkspur, 420 on Golden Gate Ferry\'s other routes, and 400 on SF Bay Ferry';
const hh = (h: number) => (h === 0 ? 'midnight' : h === 12 ? 'noon' : h < 12 ? `${h} a.m.` : `${h - 12} p.m.`);

/** where capacity at boarding binds in the base run (CAP, from baseline.ts) */
function capacityResults(): string {
  const c = CAP!;
  const P = ['AM', 'MD', 'PM', 'NT'] as const;
  const total = P.reduce((a, p) => a + c.leftBehind[p], 0), boards = P.reduce((a, p) => a + c.boardings[p], 0);
  const name = (r: { feed: string; route: string; mode: string; headsign: string }) => (r.feed === 'muni' ? (r.mode === 'cablecar' ? `the ${r.route === 'PH' ? 'Powell–Hyde' : r.route === 'PM' ? 'Powell–Mason' : 'California'} cable car` : `the ${r.route}`) : r.feed === 'ggt' ? (r.mode === 'ferry' ? 'the Larkspur ferry' : `Golden Gate Transit's ${r.route}`) : r.feed === 'caltrain' ? 'Caltrain' : r.feed === 'ferry' ? `the ${r.route} ferry` : `${r.feed} ${r.route}`);
  const per = { AM: 'in the morning peak', MD: 'at midday', PM: 'in the evening peak', NT: 'at night' } as Record<string, string>;
  const top = c.routes.slice(0, 4).map((r) => `${name(r)} toward ${r.headsign.replace(/ \+ .*/, '').replace(/`/g, '’')} ${per[r.p]} (${int(r.leftBehind)}, ${pc(r.share, 1)} of its boardings)`);
  const g = (k: string) => c.byGroup?.[k] ?? 0;
  // the route directions SFMTA's counters flag as most often crowded (sfmtaCrowding), and which of them the model leaves riders behind on
  const flagged = ['1', '38R', '45', '30X', '5R', '2'];
  const hit = flagged.filter((f) => c.routes.some((r) => r.feed === 'muni' && r.route === f));
  return `<p>In the base run, ${int(total)} boardings a weekday, ${pc(total / boards, 1)} of all, are made by riders left behind by at least one full vehicle (${list(
    [['muniBus', "Muni's buses"], ['cableCar', 'the cable cars'], ['streetcar', 'the historic streetcars'], ['muniMetro', 'Muni Metro'], ['regionalBus', 'the regional buses'], ['caltrain', 'Caltrain'], ['ferry', 'the ferries'], ['bart', 'BART']]
      .filter(([k]) => k === 'muniMetro' || g(k) >= 1)
      .map(([k, label]) => `${label} ${int(g(k))}`),
  )}); the most are on ${list(top)}. SFMTA's passenger counters flag the 1, 38R, 45, 30X, 5R, and 2 as the routes most often above its crowding capacity, which is lower than the places used here ${cite('sfmtaCrowding')}; ${hit.length ? `the model leaves riders behind on ${list(hit.map((r) => `the ${r}`))}` : 'the model leaves riders behind on none of them'}${hit.length < flagged.length ? `. It finds fewer full vehicles than the counts because it spreads each hour's riders evenly over that hour's vehicles, while the counts flag single trips` : ''}. In the Market Street subway the 2024 peak hour carried about 65 to 88 riders a car ${cite('sfmtaMetroCapacity')}, below the 119 places used here.</p>`;
}

/** trip mode choice conditional on tour mode: names, NHTS 2017 (nhts-tripmode.json), and the table of what each tour mode allows */
const MODE_LOWER: Record<string, string> = { da: 'drive alone', sr: 'carpool', tnc: 'ride-hail', transit: 'transit', walk: 'walk', bike: 'bike' };
const MODE_TITLE: Record<string, string> = { da: 'Drive alone', sr: 'Carpool', tnc: 'Ride-hail and taxi', transit: 'Transit', walk: 'Walk', bike: 'Bike' };
type TripRef = { tours_sample: number; otherTrips: Record<string, number>; otherTripsUnder3mi: Record<string, number>; toursWithATripBy: Record<string, number>; toursWithAnotherMode: number; returnLegByPeriod: Record<string, Record<string, number>> };
const TRIP_TM1: Record<string, string> = { 'da>sr': 'not allowed', 'walk>transit': 'not allowed', 'walk>sr': 'not allowed', 'bike>walk': fx(-12.708, 2) };
function tripModeTable(calibrated?: Record<string, number>): string {
  const NH = REF.nhtsTripMode.byTourMode as unknown as Record<string, TripRef>;
  const rows = (['da', 'sr', 'transit', 'walk', 'tnc', 'bike'] as const).map((M) => {
    const sw = TRIP_SWITCH.filter(([a]) => a === M);
    const n = NH[M];
    const k = (m: string) => `${M}>${m}`;
    return [
      MODE_TITLE[M],
      list(sw.map(([, m]) => MODE_LOWER[m])),
      sw.map(([, m]) => `${MODE_LOWER[m]}: ${TRIP_TM1[k(m)] ?? fx(TRIP_SWITCH_ASC[k(m)], 2)}`).join('; '),
      ...(calibrated ? [sw.map(([, m]) => fx(calibrated[k(m)] ?? TRIP_SWITCH_ASC[k(m)], 2)).join('; ')] : []),
      n ? int(n.tours_sample) : '–',
      n ? sw.map(([, m]) => pc((M === 'walk' ? n.otherTripsUnder3mi : n.otherTrips)[m] ?? 0, 1)).join('; ') : '–',
    ];
  });
  return table(
    'tripmodes',
    'Trip modes allowed by each tour mode, with their constants, and the share of the other trips of NHTS tours by those modes.',
    ['Tour mode', 'Other trip modes', 'TM1 constant (work trips)', ...(calibrated ? ['Calibrated constant'] : []), 'NHTS tours', 'NHTS: other trips by those modes'],
    rows,
    { wide: true, notes: `The tour's own mode is always allowed, with constant zero. TM1 constants are from the Work sheet of TripModeChoice.xls ${cite('tm1Code')}, relative to the tour's own mode: on carpool tours, relative to TM1's two-person shared ride; on ride-hail tours, relative to single-rider TNC. TM1 does not allow the trip modes marked "not allowed"; their starting values (${fx(TRIP_SWITCH_ASC['da>sr'], 0)}, ${fx(TRIP_SWITCH_ASC['walk>transit'], 0)}, and ${fx(TRIP_SWITCH_ASC['walk>sr'], 0)}) were assumed, as was the bike tour's walking constant (${fx(TRIP_SWITCH_ASC['bike>walk'], 0)}, against TM1's ${fx(-12.708, 1)}), and all were then fitted. NHTS: 2017, weekdays, residents of the San Francisco–Oakland CBSA in tracts of 17,000 or more people per square mile; a tour's mode is that of its trip into the primary destination, and its other trips are the trip back and the trips through stops; for walking tours, only those under 3 miles ${cite('nhts2017')}.` },
  );
}

/** the walk network's repairs (diag-walk.ts, streets.ts) */
function walkJoins(): string {
  const J = F.streetJoins, R = F.walkRules, N = F.walkNet?.now;
  if (!J) return '';
  return `Four repairs were made for walking: walkways that cross on the same level were joined where they cross (${int(J.crossings)} places; never at bridges, tunnels, covered or indoor ways, or across layers, which left ${int(J.apartLevels)} crossings apart), a walkway ending within ${R.nearMissM} m of another was joined to it unless a fence, wall, freeway, or railway lies between (${int(J.nearMisses)} joined, ${int(J.nearMissesBarred)} not), plazas mapped as areas are crossed in straight lines (${int(J.areaLinks)} links across ${int(J.areas)} plazas), and gates closed to the public (${int(J.gates)}) end the way.${N ? ` From each census block to the stops 200 to 800 m from it, weighted by residents and jobs, the walk is a median ${fx(N.circuity.median)} times the straight line.` : ''}`;
}

/** driving and cycling start and end where a trip can both arrive and leave (skims.ts mainPieces) */
function reachAndLeave(): string {
  const N = F.walkNet?.now?.zones;
  const text = 'Trips by car and by bicycle start and end only on the part of their network that can be both reached and left';
  if (!N) return `${text}.`;
  return `${text}. By median road distance to the other zones, ${N.car.over2_5 + N.bike.over2_5 === 0 ? 'no zone is' : `${nw(N.car.over2_5)} zones by car and ${nw(N.bike.over2_5)} by bike are`} more than 2.5 times the straight line.`;
}

/** the regional legs where the freeways' speeds are published (skims.ts, regional-legs.ts; ext-auto-times.json from diag-extauto.ts) */
function extLegs(): string {
  const m = (PTJ as unknown as { corridorMph?: Record<string, Record<'N' | 'S', Record<'AM' | 'PM', number>>> }).corridorMph;
  const eb = eastBayCorridors(EBJ as never);
  const E = EXT as unknown as Record<string, { rows: { name: string; toFiDi: number; assignmentToFiDi: number }[] } | undefined>;
  if (!m || !eb) return '';
  const pa = E.after?.rows.find((r) => r.name === 'Palo Alto');
  return ` Where freeway speeds are published, the legs run at them, at 65 mph off the peaks: from the Peninsula and the South Bay, at the speeds of C/CAG's monitored San Mateo segments (into the city in the morning, ${fx(m['US-101'].N.AM, 0)} mph on US-101 and ${fx(m['I-280'].N.AM, 0)} on I-280) ${cite('ccagCmp2025')}, and from the East Bay, at those of Alameda CTC's segments along the zone's corridor (${fx(eb.routes['I-80'].in.AM, 0)} mph on I-80, ${fx(eb.routes['SR-24'].in.AM, 0)} on SR-24, ${fx(eb.routes['I-580'].in.AM, 0)} on I-580, and ${fx(eb.routes['I-880'].in.AM, 0)} on I-880), then the Bay Bridge's approach and metering lights at ${fx(eb.last!.in.mph.AM, 0)} mph ${cite('actcLos2024')}. These speeds include the queues. Marin's legs keep the assumed speed, since its latest published speeds date from the pandemic.${pa ? ` The morning drive from Palo Alto to the Financial District takes ${fx(pa.toFiDi, 0)} minutes, against ${fx(pa.assignmentToFiDi, 0)} in the road assignment (${sec('roads')}).` : ''}`;
}

/** why commuting follows BATS's stated frequency and not its travel diaries (commute-days.json, commute-basis.json) */
function commuteDaysParagraph(): string {
  const D = COMMUTE.days as unknown as { bats2023Diary: { sanFrancisco: Record<'2019' | '2023', { commutedShare: number; didNotWorkShare: number }> }; bartDayOfWeek2025: { tueThuOverMonFriMean: number } };
  const R = (COMMUTE.basis as unknown as { runs: Record<string, { bartAmDowntown: { ratio: number }; bartCityExitsAmShare: number; bartCityExits: { r: number; pctRmse: number }; muni: { r: number; pctRmse: number } }> }).runs;
  const d = D.bats2023Diary.sanFrancisco;
  const ftw = (ABMR.val as unknown as { fullTimeWorkers: { commuteShare: number } }).fullTimeWorkers.commuteShare;
  const amObs = 0.4672; // BART's city exits in the morning peak, share of the weekday (bart-hourly, 2025)
  const s = R['agg-stated'], dd = R['agg-diary'];
  return `<p>BATS 2023's travel diaries give a lower rate: San Francisco's full-time workers went to work on ${pc(d['2023'].commutedShare, 0)} of diary days ${cite('batsDashboard')}, against the ${pc(ftw, 0)} of weekdays that the stated frequency gives a full-time worker. The model keeps the stated frequency. The diaries are weighted on Tuesdays to Thursdays only ${cite('bats2023')}, when BART's morning exits downtown are ${fx(D.bartDayOfWeek2025.tueThuOverMonFriMean, 2)} times their Monday and Friday mean ${cite('bartHourly')}, so a diary day should show more commuting than an average weekday, not less; in 2019 they had only ${pc(d['2019'].commutedShare, 0)} of full-time workers commuting; and office attendance has risen since fall 2023 ${cite('kastle', 'sfControllerEconomy', 'bayAreaCouncilRto')}. Both rates were tested with the model recalibrated. The diaries' rate gives ${pc(dd.bartAmDowntown.ratio, 0)} of BART's counted morning-peak exits at the downtown stations and puts ${pc(dd.bartCityExitsAmShare, 0)} of the city's BART exits in the morning peak (counted: ${pc(amObs, 0)}); the stated frequency gives ${pc(s.bartAmDowntown.ratio, 0)} and ${pc(s.bartCityExitsAmShare, 0)}, with BART's exits by station at r = ${fx(s.bartCityExits.r, 2)} against ${fx(dd.bartCityExits.r, 2)} and Muni's routes fitting equally either way.</p>`;
}

/** the synthetic population (synpop.ts) and the comparison of demand's segments (synpop-bridge.ts) */
function synpopText(): string {
  const P = SYNPOP.pop, B = SYNPOP.bridge;
  const fitOf = (name: string) => P.controlFit.find((c) => c.control === name)!;
  const groups: [string, string, string[]][] = [
    ['Households', 'block group', ['households']],
    ['Households by size (1, 2, 3, 4+)', 'block group', ['size1', 'size2', 'size3', 'size4+']],
    ['Households by vehicles (0, 1, 2, 3+)', 'block group', ['veh0', 'veh1', 'veh2', 'veh3+']],
    ['Households by income (four bands)', 'block group', ['inc<50k', 'inc50-100k', 'inc100-200k', 'inc200k+']],
    ['Persons in households', 'block group', ['persons']],
    ['Persons by age (eight groups)', 'block group', ['age0-4', 'age5-17', 'age18-24', 'age25-34', 'age35-49', 'age50-64', 'age65-79', 'age80+']],
    ['Persons by sex', 'block group', ['male', 'female']],
    ['Employed residents', 'block group', ['employed']],
    ['Households by workers (0, 1, 2, 3+)', 'tract', ['workers0', 'workers1', 'workers2', 'workers3+']],
    ['Persons by school level (preschool, K–12, undergraduate, graduate)', 'tract', ['preschool', 'gradeK-12', 'undergraduate', 'graduate']],
  ];
  const range = (v: number[]) => (Math.min(...v) === Math.max(...v) ? fx(v[0], 1) : `${fx(Math.min(...v), 1)}–${fx(Math.max(...v), 1)}`);
  const rows = groups.map(([label, geo, names]) => {
    const f = names.map(fitOf);
    return [label, geo, int(f.reduce((a, x) => a + x.total, 0)), int(f.reduce((a, x) => a + x.synthetic, 0)), range(f.map((x) => x.pctRmse)), range(f.map((x) => x.pctRmseBalanced))];
  });
  const hhFits = P.controlFit.filter((c) => /^(size|veh|inc)/.test(c.control)).map((c) => c.pctRmse);
  const ageFits = P.controlFit.filter((c) => c.control.startsWith('age')).map((c) => c.pctRmse);
  const X = P.crosstabs as Record<string, { cells: number; srmse: number; maxDiffPts: number }>;
  const xMax = Math.max(...Object.values(X).map((x) => x.maxDiffPts));
  const R = B.results as Record<string, { residentModeShares: Record<string, number> }>;
  const Zf = B.zones as Record<string, { transitShareByHomeZone: { r: number; rmsePts: number } }>;
  const I = B.inputs as Record<string, Record<'commuters' | 'youth', Record<string, number>>>;
  const FR = B.fullRun as unknown as Record<string, { muniBoardings: number; routesVsOff: { r: number; maxRelDiff: number } }>;
  const tr = (m: string) => R[m].residentModeShares.transit;
  const S = P.summary;
  return `<p>SF-TRACE also carries a synthetic population of San Francisco, one record per household and person, which the person-level layer (${sec('abm')}) uses. It is built as PopulationSim builds the populations of SF-CHAMP and Travel Model Two ${cite('populationsim')}. The seed records are the ACS 2020–24 five-year microdata of the city's eight PUMAs: ${int(S.seedHouseholds)} households and ${int(S.seedGroupQuartersPersons)} residents of group quarters ${cite('pumsSeed')}. Each block group's seed households are weighted so that its households and persons add up to its ACS counts, with household and person controls met together as in iterative proportional updating ${cite('ye2009', 'acs')} (${tab('synpop')}). Weights are balanced first by PUMA and then, tract by tract, in each block group by PopulationSim's list balancer, which stays as close as it can in relative entropy to the PUMS weights, and are then rounded to whole households, keeping each block group's count. The whole city takes about 45 seconds.</p>
<p>Residents of group quarters (${int(S.groupQuartersResidents)}, ${pc(S.groupQuartersResidents / S.persons, 1)} of the city) are drawn separately, as one-person records, split among institutions, college housing, and other group quarters as the 2020 census counted them in each block group ${cite('pl94')}. Each person is given TM1's person type. Working from home is drawn at the rate of the 2024 records of the same person type and income band, scaled to the ACS 2024 share, since the seed's 2020 and 2021 records have far more of it.</p>
<p>The population has ${int(S.households)} households and ${int(S.persons)} persons. Across block groups its %RMSE against the controls is ${fx(Math.min(...hhFits), 1)}–${fx(Math.max(...hhFits), 1)}% for households by size, vehicles, and income, and ${fx(Math.min(...ageFits), 1)}–${fx(Math.max(...ageFits), 1)}% for persons by age; nearly all of the difference is left by balancing, not by rounding. Joint distributions that were not controlled (households by vehicles, income, and size; by workers and vehicles; persons by age and employment; persons by type) differ from the PUMS citywide by at most ${fx(xMax, 2)} percentage points in any cell.</p>
<p>The population was also used to test the residents' groups. Counted from the synthetic households instead of raked, residents' transit share is ${fx(tr('households'), 2) === fx(tr('off'), 2) ? `${fx(tr('off'), 2)}% either way` : `${fx(tr('households'), 2)}%, against ${fx(tr('off'), 2)}% with the raked shares`}, the transit share by home zone agrees to ${fx(Zf.households.transitShareByHomeZone.rmsePts, 2)} percentage points (RMSE), and every counted Muni route's boardings are within ${pc(FR.households.routesVsOff.maxRelDiff, 2)} of the calibrated run's. Split instead by the households each person lives in, ${pc(I.persons.commuters.car0 / 100, 1)} of commuters and ${pc(I.persons.youth.car0 / 100, 1)} of children live in households without a car, where the person-weighted raked shares put ${pc(I.off.commuters.car0 / 100, 1)} and ${pc(I.off.youth.car0 / 100, 1)}; residents' transit share then falls to ${fx(tr('persons'), 2)}% and Muni's boardings by ${pc(1 - FR.persons.muniBoardings / FR.off.muniBoardings, 1)}. The constants were calibrated with the raked shares, so that version would need recalibration before use.</p>
${table(
  'synpop',
  'Controls of the synthetic population and its fit.',
  ['Control', 'Geography', 'Control total', 'Synthetic', '%RMSE across zones', 'Before rounding'],
  rows,
  { numeric: [2, 3, 4, 5], wide: true, notes: `Controls from ACS 2020–24 tables B11001, B11016, B25044, B19001, B25008, B01001, B23025 (block groups) and B08202, B14001 (tracts) ${cite('acs')}; persons are those in households (group quarters taken out). %RMSE is the root mean square difference across the ${int(fitOf('households').zones)} block groups or ${int(fitOf('workers0').zones)} tracts over the mean control, given as a range over the categories. Computed by <code>synpop.ts</code>.` },
)}`;
}

/** car ownership: TM1's model, its fit (calibrate-autoown.ts), and the long-run test (autoown-longrun.json) */
function autoOwnText(): string {
  const ao = FX.calibration.autoOwn;
  const fit = (() => {
    if (!ao?.fit) return '';
    const f = ao.fit;
    const share = (k: number) => pc(f.city[k][1], 1);
    const r3 = (v?: number[]) => (v ? v.map((x) => fx(x, 0)).join(' / ') : '–');
    return `<p>TM1's coefficients were kept and its constants (with its San Francisco county terms) refitted to the city's households by cars: ${share(0)} without a car, ${share(1)} with one, ${share(2)} with two, ${share(3)} with three, and ${share(4)} with four or more. Each of ${ao.nhoods} analysis neighborhoods ${cite('datasfNhoods')} has a constant on one car and on two or more, in the role of SF-CHAMP's district constants. As published, TM1 gives the city ${f.cityTM1 ? pc(f.cityTM1[0], 0) : 'too few'} of households without a car. By block group the remaining error is no larger than the ACS's own sampling error (${tab('autoown')}).</p>
${table(
  'autoown',
  'Fit of the car ownership model to ACS 2020–24 B25044: %RMSE of households with no car, one car, and two or more, over block groups and over neighborhoods.',
  ['Constants', 'Block groups', 'Neighborhoods'],
  [
    ['TM1 as published (with its San Francisco terms)', r3(f.zoneTM1), '–'],
    ['City-wide, refitted', r3(f.zoneCityOnly), r3(f.nhoodCityOnly)],
    ['City-wide and by neighborhood', r3(f.zonePctRmse), r3(f.nhoodPctRmse)],
    ['ACS sampling error alone', r3(f.samplingFloor), '–'],
  ],
  { numeric: [1, 2], notes: 'Root mean square error over the mean count, in percent; zones with no households are left out. Computed by <code>calibrate-autoown.ts</code> on the base run’s skims.' },
)}`;
  })();
  const L = LONGRUN;
  const test = L
    ? `<p>The test is the Geary subway of the application's examples. Within 800 m of its stations, ${int(L.corridor.hh)} households' transit accessibility term rises by ${fx(L.corridor.accessGain, 3)} (jobs reachable by transit within 45 minutes change by ${fx(L.corridor.jobs45Pct, 1)}%), and the model lowers their cars by ${fx(-L.corridor.carsPct, 2)}% and raises their households without a car by ${fx(L.corridor.noCarPct, 2)}%; citywide, cars fall ${fx(-L.city.carsPct, 2)}%. A residential sorting model of the Copenhagen area, which lets households move as well as change their cars, put the effect of the 17-station City Ring metro at −2.3% to −3.4% of the area's cars ${cite('mulalic2020')}. The long run adds ${int(L.transit.long - L.transit.short)} transit trips a weekday to the short run's ${int(L.transit.short - L.transit.base)}.</p>`
    : '';
  return `<p>Households' cars enter mode choice: households without a car cannot drive alone. An ordinary scenario run keeps each zone's split by cars as ACS table B25044 gives it, as for a change that has just opened. A long-run run, an option, lets households choose again how many cars to own at the scenario's accessibility, as TM1, ActivitySim, and SF-CHAMP do. The model is TM1's auto ownership model with its published coefficients ${cite('tm1AutoOwn')}, also implemented in ActivitySim's prototype_mtc ${cite('asimMtcAo')}: a multinomial logit over 0, 1, 2, 3, and 4 or more cars,</p>
${display('autoown', `V_{hk} = \\alpha_k + \\delta_{n(h)k} + \\boldsymbol{\\beta}_k^{\\top}\\mathbf{x}_h + \\gamma^{\\text{car}}_{w(h)}\\,A^{\\text{car}}_{z} + \\gamma^{\\text{tr}}_{w(h)}\\,A^{\\text{tr}}_{z} + \\gamma^{\\text{walk}} A^{\\text{walk}}_{z} + \\theta_k\\,\\bar{s}_{z}\\,\\mathbb{1}[w_h > 0],\\qquad V_{h0} = 0`)}
<p>where ${math('\\mathbf{x}_h')} holds the household's persons aged 16 and over (dummies for two, three, and four or more), persons aged 16–17, 18–24, and 25–34, the presence of children aged 0–4 and 5–17, workers (up to three), income in two linear pieces (thousands of 2000 dollars, deflated by the CPI-U ${cite('blsCpiUs')}), and the zone's density index. The accessibility terms are TM1's, ${math('A^{m}_z = 0.66\\,\\ln(1 + \\sum_d E_d\\, e^{-0.05\\, t^{m,\\text{pk}}_{zd}}) + 0.34\\,\\ln(1 + \\sum_d E_d\\, e^{-0.05\\, t^{m,\\text{op}}_{zd}})')}, with ${math('E_d')} retail jobs and ${math('t')} round-trip minutes in the peak and off-peak, and on foot ${math(`\\ln(1 + \\sum_d E_d\\, e^{${AO_ACCESS.dispWalk}\\, \\ell_{zd}})`)} over round trips of up to ${AO_ACCESS.maxWalkMiles} miles ${math('\\ell')}. Their coefficients are the same for every number of cars, so better transit lowers the utility of owning any car against none (${math(`\\gamma^{\\text{tr}} = ${fx(TM1_AO.transitAccess[0], 4)}`)} without workers and ${fx(TM1_AO.transitAccess[1], 4)} with them). Households with workers also weigh ${math('\\bar{s}_z')}, the mean over the zone's commute flows of the round-trip time a car saves against the quicker of transit and walking, divided by 120 minutes and held within ±1. The times are SF-TRACE's own skims; outside the city, MTC's 2023 retail employment${ao ? ` (${int(ao.retailOutside)} jobs)` : ''} is assigned to the nearest external zone ${cite('tm1Code')}. Households enter as classes: the 3,767 San Francisco households of the ACS 2024 PUMS ${cite('acsPums1yP')} were reweighted to each block group's households by income (B19001), by size and workers (B08202, scaled from the tract), and persons by age (B01001) ${cite('acs')}, by iterative proportional updating ${cite('ye2009')}, and grouped by drivers, workers, and income class${ao ? ` (${fx(ao.classes / F.counts.zones, 1)} classes a block group on average)` : ''}; car ownership was not a control.</p>
${fit}
<p>A long-run run pivots on the census: within each income class, each zone's households are moved between car segments by the ratio of the model's shares at the scenario's accessibility to its shares in the base run (an incremental logit), so a long-run run with no changes reproduces the base. It does not include households moving toward better transit, a large part of the long-run effect in published work, and TM1's accessibility terms carry no fares, so a fare change does not move car ownership; Goodwin ${cite('goodwin1992')} and Dargay and Hanly ${cite('dargay1999')} put the long-run elasticity of car ownership with respect to transit fares at +0.1 to +0.4.</p>
${test}`;
}

/** the person-level layer (abm.ts; abm-calibrate.ts, abm-validate.ts, abm-check.ts, abm-compare.ts) */
function abmSection(): string {
  const V = ABMR.val as unknown as {
    segments: number; householdSegments: number;
    stayHome: { model: number; bats2023: number };
    byPtype: Record<string, { persons: number; pattern: Record<'M' | 'N' | 'H', number>; patternNhts2017: Record<'M' | 'N' | 'H', number>; workTours: number; schoolTours: number; nonMandatoryTours: number; tripsPerPerson: number; tripsPerPersonNhts2017: number }>;
    adults: { tripsPerPerson: number; bats2023: number };
    fullTimeWorkers: { tripsOnCommuteDays: number; tripsOtherDays: number; bats2023: { commuted: number; notCommuted: number } };
    school: { residentsK12Tours: number; enrollmentOnAverageWeekday: number };
    workplaces: { shareCorrelation: number; dissimilarity: number; outOfCity: { model: number; census: number }; distanceScale: number };
  };
  const G = ABMR.agg as unknown as { persons: number; secondsSegments: number; secondsPersons: number; citywide: Record<string, { diffPct: number }>; zones: Record<string, { pctRmse: number }> };
  const A = ABMR.fit as unknown as Record<'aggregate' | 'abm', { demandSeconds: { whole: number; part: number }; muni: { r: number; pctRmse: number }; bartCityExits: { r: number }; T: number }>;
  const PT = ['Full-time worker', 'Part-time worker', 'University student', 'Non-worker', 'Retired', 'Student 16+', 'Child 6–15', 'Child under 6'];
  const rows = PT.map((name, k) => {
    const r = V.byPtype[k + 1];
    return [name, int(r.persons), `${fx(r.pattern.M, 2)} / ${fx(r.pattern.N, 2)} / ${fx(r.pattern.H, 2)}`, k === 7 ? '–' : `${fx(r.patternNhts2017.M, 2)} / ${fx(r.patternNhts2017.N, 2)} / ${fx(r.patternNhts2017.H, 2)}`, fx(r.workTours + r.schoolTours, 2), fx(r.nonMandatoryTours, 2), fx(r.tripsPerPerson, 2), k === 7 ? '–' : fx(r.tripsPerPersonNhts2017, 2)];
  });
  const kinds = ['work', 'school', 'shop', 'other', 'social'];
  const aggMax = Math.max(...kinds.map((k) => Math.abs(G.citywide[k].diffPct)));
  const zMax = Math.max(...kinds.map((k) => G.zones[k].pctRmse));
  const W = V.fullTimeWorkers;
  const ag = A.aggregate, ab = A.abm;
  // the delivered bundle's calibration.abm.on (export-facts.ts abmOn); absent means off, as demand.ts reads it
  const abmOn = (F.calibration as { abmOn?: boolean }).abmOn ?? false;
  return section('abm', 'Person-level choices', `
<p>Residents' tours can also be made person by person from the synthetic population (${sec('population')}), as in SF-CHAMP and ActivitySim. The layer is optional and is switched by the bundle's calibration; it is ${abmOn ? 'on' : 'off'} in the delivered model, whose residents' tours ${abmOn ? 'come from it' : 'come from the aggregate tour rates'}. Its models are those of ActivitySim's prototype_mtc, the open-source port of TM1, with its published coefficients and constants calibrated to San Francisco ${cite('asimMtc', 'activitysim', 'tm1Code')}: the coordinated daily activity pattern (CDAP), in which each household member has a mandatory day, a non-mandatory day, or stays home; mandatory and non-mandatory tour frequency; and usual workplace and school location. ActivitySim draws each person's choices at random; here every choice is taken in expected value, so a scenario's differences carry no simulation noise.</p>
<p>Households identical in everything the CDAP reads form ${int(V.householdSegments)} household segments, and the CDAP is solved exactly for each over every combination of its first five members' patterns. Members are then pooled into ${int(V.segments)} person segments, and tour frequency is solved at each segment's mean characteristics. Solved instead person by person (${int(G.persons)} persons), expected tours differ by at most ${fx(aggMax, 1)}% citywide for any kind of tour and by ${fx(zMax, 1)}% or less across zones (%RMSE), at ${fx(G.secondsPersons, 0)} seconds for the whole city on one thread against ${fx(G.secondsSegments, 1)}. Accessibility is TM1's, computed from each run's skims, so a scenario changes how many tours people make. Workplaces are chosen by car segment and income band with TM1's workplace model (its distance terms scaled by a calibrated ${fx(V.workplaces.distanceScale, 2)}, 0.3 on the work tour's logsum, and its size terms by income on LODES jobs ${cite('lodes')}), with shadow prices holding each workplace to the census flows and schools to their enrollment ${cite('cdeEnroll')}. Workplace shares by home neighborhood and workplace neighborhood or county then correlate at ${fx(V.workplaces.shareCorrelation, 2)} with the census flows (index of dissimilarity ${fx(V.workplaces.dissimilarity, 2)}), with ${pc(V.workplaces.outOfCity.model, 1)} of commutes leaving the city against ${pc(V.workplaces.outOfCity.census, 1)}.</p>
<p>Workers' mandatory constants are calibrated to the aggregate commuting rate (${fx(ATTENDANCE, 3)} of weekdays, ${sec('tours')}); students' and children's to NHTS 2017's mandatory-day shares by person type ${cite('nhts2017')}; staying home to BATS 2023's share, ${pc(V.stayHome.bats2023, 1)} (model ${pc(V.stayHome.model, 1)}) ${cite('bats2023t50')}; and non-mandatory tours to NHTS's rates by person type and purpose (${tab('abm')}). Not fitted: full-time workers make ${fx(W.tripsOnCommuteDays, 2)} trips on a commuting day and ${fx(W.tripsOtherDays, 2)} on other days, against BATS 2023's ${fx(W.bats2023.commuted, 2)} and ${fx(W.bats2023.notCommuted, 2)} ${cite('batsDashboard')}; adults make ${fx(V.adults.tripsPerPerson, 2)} trips a weekday against ${fx(V.adults.bats2023, 2)}; and residents make ${int(V.school.residentsK12Tours)} school tours to the city's K–12 schools a weekday, against ${int(V.school.enrollmentOnAverageWeekday)} expected from enrollment on an average weekday (assumed 180 school days and 94% attendance). Recalibrated, the person-level layer fits the counts about as the aggregate rates do: Muni routes at r = ${fx(ab.muni.r, 3)} and %RMSE ${fx(ab.muni.pctRmse, 1)}% against ${fx(ag.muni.r, 3)} and ${fx(ag.muni.pctRmse, 1)}%, BART's exits at the city's stations at r = ${fx(ab.bartCityExits.r, 3)} against ${fx(ag.bartCityExits.r, 3)}, and the T at ${pc(ab.T, 0)} of its count against ${pc(ag.T, 0)}. Demand takes ${fx(ab.demandSeconds.part, 1)} seconds in each of four workers against ${fx(ag.demandSeconds.part, 1)}. Its calibration is kept apart (<code>server/beta3/reference/abm-calibration.json</code>). Tours keep the NHTS time-of-day shares rather than hourly schedules, and joint tours are not modeled apart.</p>
${table(
  'abm',
  'Person-level choices by person type: day patterns, tours, and trips per person.',
  ['Person type', 'Persons', 'M / N / H', 'NHTS 2017 M / N / H', 'Mandatory tours', 'Non-mandatory tours', 'Trips', 'NHTS 2017 trips'],
  rows,
  { numeric: [1, 4, 5, 6, 7], wide: true, notes: `Expected values per person on an average weekday. M, N, H: mandatory, non-mandatory, and home days (CDAP). Workers' M is fitted to the aggregate model's commuting rate and everyone's H to BATS 2023's share staying home, so they differ from NHTS 2017's by design. Trips are tours' legs with the NHTS stop and subtour rates; NHTS trips include walking legs to transit counted as trips. NHTS has no trips for children under 5. Computed by <code>abm-validate.ts</code>.` },
)}
`);
}

export function model(): string {
  const C = F.counts, S = F.streets;
  // the cost of a change of lines in route choice, at the delivered calibration (params.ts transferPenalty)
  const xferMin = transferPenalty(FX.calibration);
  const sp = REF.autoSpeeds.citywide, hp = REF.autoSpeeds.hourlyProfile.byModelPeriod;
  const bart = F.bartFare;
  const feeds = F.counts.byFeed as Record<string, { patterns: number; routes: number }>;
  const AG: Record<string, string> = { muni: 'Muni', bart: 'BART', caltrain: 'Caltrain', ggt: 'Golden Gate Transit', ferry: 'ferries', ac: 'AC Transit', samtrans: 'SamTrans', tma: 'Mission Bay TMA shuttles', shuttle: 'UCSF and PresidiGo shuttles and the Treasure Island Ferry' };
  const tr = F.calibration.touristRides as Record<string, number>;
  const TOUR: Record<string, string> = { PM: 'Powell–Mason', PH: 'Powell–Hyde', CA: 'California', E: 'E Embarcadero', F: 'F Market & Wharves' };
  const cw = COEFFS.work, cs = COEFFS.school, co = COEFFS.shop;
  const cc = (c: number, v: number) => fx((60 * c) / v, 4);
  const NT = REF.nhtsTours.byTourPurpose as Record<string, { tours_sample: number; toursPerPersonWeekday: number; meanDetourLegKmDense: number; meanPrimaryKmDense: number; halfToursWithStop: number; stopsPerHalfWithStop: number; stopNearHomeShare: number; workSubtoursPerTour: number | null }>;
  const NM = REF.nhtsTours.byTourMode as Record<string, { tours_sample: number; stopsPerHalf: number; meanDetourLegKmDense: number }>;
  const nhtsTrip = REF.nhtsTripMode.byTourMode as unknown as Record<string, TripRef>;
  const hv = REF.hhVehInc.perHousehold.shareByVehicles;
  const persons = REF.nhtsPersons.personShare;
  const ST = REF.students;
  const counties = Object.entries(COMMUTE_DAYS).filter(([c]) => c !== 'San Francisco');
  const cdMin = counties.reduce((a, b) => (b[1] < a[1] ? b : a)), cdMax = counties.reduce((a, b) => (b[1] > a[1] ? b : a));
  const shuttleTotal = Object.values(SHUTTLE_RIDERS).reduce((a, v) => a + v, 0);
  const sh = FX.shuttles, sc = FX.schools, rel = FX.reliability, park = FX.parking, night = FX.night, op = FX.operations;
  const opRange = (o: Record<string, number> | null | undefined) => {
    const v = Object.values(o ?? {}).filter((x) => x !== undefined && x !== null);
    return v.length ? [Math.min(...v), Math.max(...v)] : null;
  };
  const allRun = opRange(op?.runRatio.all), metroRun = opRange(op?.runRatio.metro);
  const age65 = FX.totals.age65plus;
  const seniorsPaying = age65 ? Math.max(0, 1 - FREE_MUNI_SENIORS / age65) : null;
  const fares = FX.fares as unknown as Record<string, { board: number; perKm: number; routes?: Record<string, number> | null }>;
  const ferryRouteFares = Object.entries(fares.ferry?.routes ?? {});
  const paidFerry = ferryRouteFares.filter(([, v]) => v > 0).map(([, v]) => v), freeFerry = ferryRouteFares.filter(([, v]) => v === 0).map(([k]) => k);
  const ctAfterMuni = Math.max(0, F.fares.caltrain.board - CLIPPER_TRANSFER_DISCOUNT);
  const bartAfterMuni = Math.max(0, (bart?.board ?? F.fares.bart.board) - CLIPPER_TRANSFER_DISCOUNT);
  const ls = LOAD_SPREAD;
  const ph = REF.peakHour.periods;
  const stopModeRef = (k: string) => NM[k]?.stopsPerHalf;
  // special events (reference/special-events.json)
  const EVR = REF.events, EA = EVR.averageWeekday, EO = EVR.model.origins.arena, EF = EVR.model.fromWork;
  const sfShare = EO.sd.reduce((a: number, x: number) => a + x, 0);
  const evT = (F.calibration as { eventTransit?: Record<string, number> }).eventTransit;
  const evSouth = (F.calibration as { eventSouthTransit?: number | null }).eventSouthTransit;
  const GC = REF.caltrainGameDay;
  const evConst = evT ? list(Object.entries(evT).map(([k, v]) => `${fx(v, 2)} at ${k}`)) : '';
  const abmOn = (F.calibration as { abmOn?: boolean }).abmOn ?? false;

  return `
${section('model', 'Model structure', `
${figure(
  'structure',
  '<div class="chart-slot" data-chart="structure"></div>',
  `SF-TRACE's structure. One pass computes transit skims for four periods, then tours and their destinations, modes, stops, and timing, then assignment for four periods; the crowding that assignment produces is averaged into the in-vehicle times of the next pass.`,
  { alt: 'Flow diagram of the model: inputs feed transit skims, tour generation, destination choice, mode choice, and stops and time of day; transit assignment then produces crowding, which is fed back into the transit skims for the next pass.' },
)}
<p>SF-TRACE represents an average weekday of travel with at least one end in San Francisco (${fig('structure')}). It is an aggregate tour-based model. Residents' travel from home is generated as tours, each with a primary destination and a mode; stops are added once the mode is chosen, and each trip of the tour then chooses its own mode among those the tour's mode allows. Demand is computed zone by zone for groups of residents defined by household car ownership, household income, and person type, not simulated person by person. An optional person-level layer built on a synthetic population can make residents' tours instead (${sec('abm')}); it is ${abmOn ? 'on' : 'off'} in the delivered model. In-commuters and visitors have generators of their own (${secs('tours', 'special')}). Destinations are chosen on mode-choice logsums, so they respond to accessibility by every mode. Transit riders are assigned by the optimal strategies of Spiess and Florian, with a crowding penalty and a limit on boarding full vehicles, both fed back to demand (${sec('assignment')}); cars are assigned by a static road assignment (${sec('roads')}).</p>
<p>The mode choice coefficients are the trip-level values of MTC's Travel Model One (TM1) ${cite('tm1Code')}, and the transit assignment follows the settings of Travel Model Two's tm2py implementation ${cite('tm2py')}. The whole model, its zone data, and its networks are written in TypeScript and run in a browser tab. The path searches, one per destination zone and period, and demand, by origin, are spread across Web Workers.${FX.bundleBytes ? ` The browser first downloads the model bundle, ${fx(FX.bundleBytes / 1e6, 1)} MB compressed.` : ''} The equations below are those implemented in <code>shared/beta3/demand.ts</code>, <code>net.ts</code>, <code>strategy.ts</code>, and <code>model.ts</code>.</p>

${section('zones', 'Zones and networks', `
<p>The ${C.zones} internal zones are the 2020 census block groups of San Francisco ${cite('census2020')}. Each carries ACS 2020–24 counts of households by vehicles available and by income, residents by age and enrollment, employed residents, and commute mode ${cite('acs')}. Working from home was taken from the five-year block-group shares, rescaled to the citywide 2024 one-year estimate of ${pc(WFH_RESIDENTS_2024, 1)}. Each zone is also represented by up to 30 points, the census blocks with the most residents and jobs, from which walk access to transit is computed.</p>
<p>Jobs were taken from LODES 2023 workplace data by block and sector ${cite('lodes')}. Because LODES places the jobs of some multi-site employers at one head-office address, the block jobs were scaled to MTC's 2023 employment within each TM1 zone and each of six sector groups ${cite('tm1Code')} (spread by land area where LODES had none). LODES reports ${int(F.totals.lodesJobs ?? 0)} jobs at San Francisco blocks; after rebalancing the zones hold ${int(F.totals.jobs)}, and ${int(F.totals.jobsMovedOut ?? 0)} jobs were taken out of block groups where LODES had more than MTC's distribution implies. College and high-school enrollment came from the same MTC land use file, and K–12 schools' enrollment from the California Department of Education (${sec('tours')}).</p>
<p>Places outside the city are ${C.external} external zones built from the LODES home-to-work flows of people who commute into or out of San Francisco. Census blocks within ${F.zonesBuild.maxExternalKm} km were grouped by city (or county outside incorporated places), groups with fewer than ${F.zonesBuild.minExternal} commuters were merged with a neighbor, and cities with more than ${int(F.zonesBuild.splitAbove)} were split by weighted k-means into parts that reach San Francisco differently, such as Oakland's hills and flats. San Francisco International Airport is its own zone, the blocks within ${(F.sfoRadiusM / 1000).toFixed(1)} km of the terminals. The external zones span ${C.externalCounties} counties (${tab('zones')}).</p>
<p>Each zone has a TM1 area type from the floating density of residents and jobs within ${F.areaTypeRadiusM} m, ${math('(\\text{pop} + 2.5\\,\\text{jobs})/\\text{acres}')}, with breaks at 300, 100, and 55 for regional core, central business district, urban business, and urban ${cite('tm1Code')}. Area type sets parking cost and the walk to and from a parked car. TM1's density index ${math('2\\,hh\\cdot jobs/\\big((hh+jobs)\\,\\text{acres}\\big)')} enters the transit and non-motorized utilities.</p>
<p>The street network is every OpenStreetMap way in the city open to cars, pedestrians, or cyclists ${cite('osm')}, including sidewalks and crosswalks mapped as ways of their own${S ? `, split at intersections into ${int(S.edges)} edges between ${int(S.vertices)} nodes (${int(S.kmWalk)} km walkable, ${int(S.kmCar)} km drivable, ${int(S.kmBikeway)} km of it with a bicycle facility)` : ''}. Who may use a way follows its most specific access tag, so a campus or park path closed to vehicles but open on foot is walkable, while a private path or a locked gate is not. ${walkJoins()} Node elevations came from USGS 3DEP terrain tiles at zoom ${F.elevationZoom} ${cite('terrain')}. Walking speed follows Tobler's hiking function ${cite('tobler')}, normalized to ${F.access.walkFlatMs} m/s on the flat, ${math('v(g) = v_0\\, e^{3.5\\cdot 0.05}\\, e^{-3.5\\,|g + 0.05|}')}. On stairs, where that function gives about half the pace people keep, a flight takes the flat walk plus ${F.walkRules.stair.upSecPerM} seconds per meter climbed and ${F.walkRules.stair.downSecPerM} per meter descended, never less than ${F.walkRules.stair.minFactor} times the flat walk ${cite('fruin')}. Cycling runs at 4.5 m/s on the flat, ${math('\\max(1.2,\\ 4.5/(1+22g))')} m/s uphill, and at most 6.75 m/s downhill; for route choice, links with a bicycle facility are weighted 0.8 and arterials without one 1.3. ${reachAndLeave()}</p>
<p>Driving times were fitted to observed speeds: freeways run at a fitted share of the posted limit (${list(Object.entries(F.auto.speedShare.freeway).map(([p, v]) => `${pc(v)} ${p}`))}), and surface streets at ${pc(F.auto.speedShare.arterial.AM)} of the limit between intersections with a fitted delay at each intersection (on arterials ${list(Object.entries(F.auto.delay.arterial).map(([p, v]) => `${v} s ${p}`))}). These reproduce SFCTA's Congestion Management Program 2025 speeds for arterials (${sp.arterial.AM} mph in the morning peak and ${sp.arterial.PM} mph in the evening peak) and freeways (${sp.freeway.AM} and ${sp.freeway.PM} mph), and SFCTA's hourly INRIX data for midday (arterials ${hp.arterial.MD} mph, freeways ${hp.freeway.MD} mph) and evening (${hp.arterial.EV} and ${hp.freeway.EV} mph) ${cite('sfctaCmp')}. Local streets, which SFCTA does not monitor, run at an assumed 80% of arterial speed. Trips from external zones drive a straight-line distance times ${F.auto.regionalCircuity} at an assumed regional speed (${list(Object.entries(F.auto.regionalSpeedKmh).map(([p, v]) => `${v} km/h ${p}`))}) to one of ${nw(F.gateways.length)} gateways (${list(F.gateways.map((g) => g.name))}), wait in a period-specific queue there, and pay the inbound tolls (${list(F.gateways.filter((g) => g.toll > 0).map((g) => `${g.name} ${money(g.toll)}`))}) ${cite('fares')}.${extLegs()}</p>
<p>The transit network was built from the GTFS schedules of ${list(F.feeds.map((f) => f.agency))} for a typical midweek day ${cite('gtfs')}; AC Transit and SamTrans routes were kept only if they stop in San Francisco. Each distinct stop sequence of a route became a line with, for each of TM1's five periods, its number of trips and its mean scheduled stop-to-stop times, which include traffic and dwell, and the number of trips leaving between 7 p.m. and midnight. Patterns with fewer than three trips a day were dropped unless they were all a route had, and rail platforms were collapsed to one node per station. Each BART hop takes the mean over all trains running it in the period, since BART's times are rounded to the minute. Muni Metro's timetable gives the downtown subway too little time (from Embarcadero to Van Ness, trains took 508 seconds outbound and 391 inbound on 15 midweek days in autumn 2025, against 300 scheduled ${cite('calitpMtcSpeeds')}), so each line's run there was scaled to the observed time in its period, except at night. The result has ${int(C.patterns)} line patterns (${list(Object.entries(feeds).map(([k, v]) => `${AG[k] ?? k} ${v.patterns}`))}) on ${C.routes} routes, serving ${int(C.stops)} stops. In a scenario, adding a stop lengthens each trip by an assumed ${STOP_LOST_SEC} seconds on buses and ${RAIL_STOP_LOST_SEC} seconds on rail, and removing one shortens it by the same amount.</p>
<p>Zones connect to stops by walking on the street network from their points, within ${F.access.busAccessMaxSec / 60} minutes for bus stops and ${F.access.railAccessMaxSec / 60} minutes for rail stations: up to three stops of each line within five minutes of the line's nearest, every rail station in reach, and for every line the stop nearest each point. Riders choose among them point by point (${sec('assignment')}). Walk transfers connect stops up to ${F.access.transferMaxSec / 60} minutes apart where a rail line is involved and up to 5 minutes between bus stops. External zones reach the regional stations from the 400 m cells where their commuters live, on foot (within 1.5 km), by an assumed local bus (10 minutes plus 1.4 times the straight-line distance at 16 km/h), or by driving to a station lot (5 minutes plus 1.4 times the distance at 32 km/h, plus half the daily fee each way), whichever is quicker. These links serve the zone's home end; trips whose outside end is an activity (residents' trips into the region, air travelers) use the zone's activity end, reached on foot or by local bus only. The airport is reached only on foot or by AirTrain.${park ? ` Lots and fees are from the operators ${cite('stationParking')}: ${park.bart} BART stations, ${park.caltrain} Caltrain stations, and ${park.ferry} ferry terminals outside the city have one.` : ''}</p>
${table(
  'zones',
  'Zone system and networks.',
  ['Element', 'Count', 'Source or rule'],
  [
    ['Internal zones (block groups)', int(C.zones), '2020 Census'],
    ['Neighborhoods', int(C.neighborhoods), 'SF Analysis Neighborhoods'],
    ['External zones', int(C.external), `LODES flows, ${C.externalCounties} counties`],
    ...(S ? [['Street nodes', int(S.vertices), 'OpenStreetMap'], ['Street edges', int(S.edges), 'OpenStreetMap']] : []),
    ['Transit stops and stations', int(C.stops), 'GTFS'],
    ['Line patterns', int(C.patterns), 'GTFS, distinct stop sequences'],
    ['Routes', int(C.routes), 'GTFS'],
    ['Zone–stop access links', int(C.accessLinks), `walk ≤ ${F.access.busAccessMaxSec / 60} min (bus), ≤ ${F.access.railAccessMaxSec / 60} min (rail)`],
    ['External zone–stop links', int(C.externalAccessLinks), 'walk, local bus, or drive to a lot'],
    ['Walk transfer links', int(C.walkTransfers), `≤ ${F.access.transferMaxSec / 60} min with rail, ≤ 5 min between buses`],
    ['Home–work flows (zone pairs)', int(C.commuteFlows), 'LODES 2023, rescaled to ACS'],
  ],
  { numeric: [1] },
)}
`)}

${section('fares', 'Fares', `
<p>Fares are modeled as pieces that the path search carries along a strategy (${tab('fares')}). Muni, BART, and Caltrain charge their boarding fare once per trip on that operator, when the rider enters it; changing lines within one of them costs nothing more, and BART's and Caltrain's distance charges are carried on the ride links. Golden Gate Transit, the ferries, AC Transit, and SamTrans charge on every ride. Muni's adult Clipper fare is ${money(MUNI_FARE)}, with free transfers within Muni for 120 minutes. A rider on a monthly or day pass pays nothing more for a ride, so the model charges the expected fare: in SFMTA's 2025 onboard survey, ${pc(MUNI_PASS_SHARE)} of Muni's paying adult riders were on such passes ${cite('sfmtaFareEquity')}, so an adult ride costs ${money(MUNI_FARE * (1 - MUNI_PASS_SHARE))}. Fare evasion, which SFMTA puts at about a fifth of riders, is not counted.</p>
<p>Under the next-generation Clipper system introduced in 2025, a rider who changes operators within two hours has up to ${money(CLIPPER_TRANSFER_DISCOUNT)} taken off each further agency's fare ${cite('clipper2')}. The model applies the discount to the boarding charge of Muni, BART, or Caltrain when a rider enters one of them from another operator, so Muni after any other operator is free, BART's boarding charge after Muni is ${bartAfterMuni === 0 ? 'waived (its distance charges remain)' : `reduced to ${money(bartAfterMuni)}`}, and Caltrain's is reduced to ${money(ctAfterMuni)}. Only cards moved to the new system, and bank cards, get it: in mid-July 2026, ${pc(CLIPPER_NEXTGEN_SHARE)} of Clipper trips were on the new system ${cite('clipperMigration')}. The rest keep the old system's discount, ${money(LEGACY_MUNI_TRANSFER_DISCOUNT)} off Muni's fare for riders who pay per ride and a free Muni ride from Daly City BART ${cite('fares')}, so each transfer is charged the mix of the two in those proportions; the share is a condition (${tab('conditions')}). </p>
<p>BART's fare was fitted as a boarding charge of ${money(bart?.board ?? 0)} plus a charge on each of its ${bart?.segments ?? 0} track segments, by least squares over every station pair in its fare table${bart ? `; across ${int(bart.pairs)} station pairs the fitted fares differ from the published ones by ${money(bart.mae)} on average (90th percentile ${money(bart.p90)})` : ''}. Caltrain and Golden Gate Transit fares were fitted as a boarding charge plus a charge per kilometer to their zone fare tables. SF Bay Ferry routes charge the fare their GTFS feed lists for the route, the lowest where several are listed${paidFerry.length ? ` (${money(Math.min(...paidFerry))} to ${money(Math.max(...paidFerry))}${freeFerry.length ? `; ${list(freeFerry)}, which ${freeFerry.length === 1 ? 'does' : 'do'} not call in San Francisco, ${freeFerry.length === 1 ? 'is' : 'are'} free` : ''})` : ''}, and AC Transit's Transbay buses and SamTrans charge the fares their feeds list. The cable cars charge ${money(CABLE_CAR_FARE)} a ride, an assumed blend of the $9 cash fare and pass use. Driving to a station lot outside the city adds half the lot's daily fee to each direction of the trip.</p>
<p>Youth and seniors (${sec('population')}) pay less. Muni is free for riders under 19, and BART and Caltrain charge youth half fare, so residents aged 5 to 17 ${PERSON_FARE.youth.inCity === 0 ? 'ride free within the city' : `pay ${pc(PERSON_FARE.youth.inCity)} of the adult fare within the city`} and pay ${PERSON_FARE.youth.outside === 0.5 ? 'half the adult fare' : `${pc(PERSON_FARE.youth.outside)} of the adult fare`} on trips leaving it. College tours to SF State pay no fare, since its students' Gator Pass is a Clipper BayPass good on every operator ${cite('gatorPass')}. Seniors pay Muni's senior fare, ${money(PERSON_FARE.senior.inCity * MUNI_FARE)}, and half elsewhere, unless enrolled in Free Muni for Seniors and People with Disabilities, which SFMTA's 2024–25 participant count implies covers about ${int(FREE_MUNI_SENIORS)} seniors ${cite('freeMuni')}. The senior fare within the city is therefore scaled by the share of residents aged 65 and over who are not enrolled${seniorsPaying !== null ? `, ${pc(seniorsPaying)}` : ''}.</p>
${table(
  'fares',
  'Fares by operator as the model charges them (adult fares, 2026).',
  ['Operator', 'Charged', 'Rule', 'Value'],
  [
    ['Muni (bus, light rail, streetcar)', 'on entering Muni', 'flat; free transfers within Muni', `${money(MUNI_FARE)} (${money(MUNI_FARE * (1 - MUNI_PASS_SHARE))} expected, with passes)`],
    ['Muni cable cars', 'each ride', 'flat (assumed blend of cash and passes)', money(CABLE_CAR_FARE)],
    ['BART', 'on entering BART; segment charges on rides', `boarding charge plus ${bart?.segments ?? 0} segment charges, fitted`, money(bart?.board ?? F.fares.bart.board)],
    ['Caltrain', 'on entering Caltrain; distance on rides', 'boarding charge plus per km, fitted', `${money(F.fares.caltrain.board)} + ${money(F.fares.caltrain.perKm, 3)}/km`],
    ['Golden Gate Transit (buses and ferries)', 'each ride', 'boarding charge plus per km, fitted', `${money(F.fares.ggt.board)} + ${money(F.fares.ggt.perKm, 3)}/km`],
    ['SF Bay Ferry', 'each ride', `GTFS fare by route${freeFerry.length ? ` (${list(freeFerry)} free)` : ''}`, paidFerry.length ? `${money(Math.min(...paidFerry))}–${money(Math.max(...paidFerry))}` : money(F.fares.ferry.board)],
    ['AC Transit Transbay', 'each ride', 'GTFS fare', money(F.fares.ac.board)],
    ['SamTrans', 'each ride', 'GTFS fare', money(F.fares.samtrans.board)],
    ['Clipper transfer discount', 'on entering Muni, BART, or Caltrain from another operator', `up to this amount off the boarding charge, for the ${pc(CLIPPER_NEXTGEN_SHARE)} of riders on the new Clipper system; the rest: ${money(LEGACY_MUNI_TRANSFER_DISCOUNT)} off Muni's fare, and Muni free from Daly City BART`, money(CLIPPER_TRANSFER_DISCOUNT)],
  ],
  { numeric: [3], wide: true, notes: `Sources: ${cite('fares')}; Clipper ${cite('clipper2')}, ${cite('transferPilotMou')}, ${cite('clipperMigration')}. Youth and senior fares are multiples of these.` },
)}
`)}

${section('population', 'Residents, the synthetic population, and car ownership', `
<p>Residents are grouped by their household's cars (none, one, or two or more) and income (under or over $100,000 a year). Each zone's households were divided among the six groups by raking the city's joint distribution of vehicles and income in the ACS 2024 microdata ${cite('acsPums1y')} to the zone's ACS counts of households by vehicles and by income. Households without a car are smaller than others: they are ${pc(hv.households[0], 1)} of the city's households but ${pc(hv.persons[0], 1)} of its residents and ${pc(hv.employed[0], 1)} of its employed residents, while households with two or more cars are ${pc(hv.households[2], 1)} of households and ${pc(hv.persons[2], 1)} of residents ${cite('acsPums1y')}. Each zone's people are therefore split by its household shares weighted by the persons, employed persons, children 5 to 17, and persons 65 and over per household of each group in the same microdata. Within each group there are three person types: youth aged 5 to 17, seniors aged 65 and over, and all other residents, children under 5 included. Youth cannot drive alone or hail a ride on their own, and youth and seniors pay the fares of ${sec('fares')}.</p>
${autoOwnText()}
${synpopText()}
`)}

${section('tours', 'Tours, stops, and work-based subtours', `
<p>Trips are grouped by purpose as in the travel surveys the model draws on: commute, school (K–12), college, shopping, errands and other, and social (social, dining, and recreation). A trip is home-based when one of its ends is the traveler's home, in either direction. Trips with <i>neither end at home</i> (travel surveys call them non-home-based) are the legs from one stop to the next on a tour (a store on the way home from work), trips from work to lunch and back, and a commuter's or visitor's trips around the city during the day.</p>
<p>Residents' travel from home is generated as tours: home to a primary destination and back, with a tour mode that bounds the modes of its trips (${sec('mode')}). Commute tours come from employed residents and their census work locations. Commuters do not commute on every weekday. BATS 2023 asked workers how often they usually commute ${cite('bats2023t45')}; counting five or more days a week as every weekday, four days as 0.8 of them, and so on down to monthly or rarer, San Francisco residents who commute do so on ${math(`f_{\\text{SF}} = ${fx(COMMUTE_DAYS['San Francisco'], 4)}`)} of weekdays, and commuters living in the other counties on ${pc(cdMin[1])} (${cdMin[0]}) to ${pc(cdMax[1])} (${cdMax[0]}). An assumed further ${pc(1 - ABSENCE)} of working days is lost to leave, holidays, and sickness. The work tours between home zone ${math('o')} and work zone ${math('d')} on a weekday are</p>
${display('commute', `T^{\\text{work}}_{od} = f_{\\text{SF}}\\, b\\, W_o\\,(1-\\omega_o)\\,\\frac{N_{od}}{\\sum_{d'} N_{od'}}`)}
<p>where ${math('W_o')} is employed residents, ${math('\\omega_o')} the share working from home, ${math(`b = ${ABSENCE}`)}, so that ${math(`f_{\\text{SF}}\\,b = ${fx(ATTENDANCE, 4)}`)}, and ${math('N_{od}')} the LODES flows. Because LODES also places too many residents' jobs outside the city, flows to external zones were reweighted to the ACS share of residents working in the city, ${pc(REF.acs.residentsPlaceOfWork_B08007.workedInSFCounty.share, 1)} of the ${int(REF.acs.residentsPlaceOfWork_B08007.totalWorkers16plus)} resident workers in table B08007. In-commuters were taken as ACS workers at San Francisco workplaces less residents working in the city, ${int(F.totals.inCommuters)} people, distributed over the LODES flows; each county's in-commuters make a work tour on ${math('f_c\\, b')} of weekdays, with ${math('f_c')} the BATS value for their home county (${fx(COMMUTE_DAYS_OTHER, 3)}, the mean, for counties BATS does not report).</p>
${commuteDaysParagraph()}
<p>Private commuter shuttles carry residents to employers in ${list(SHUTTLE_COUNTIES)}. With no SFMTA count since 2017 ${cite('sfmtaShuttles')}, their riders are taken as the residents who usually commute by bus to those counties in the ACS 2020–24 microdata ${cite('acsPums')}, times residents' attendance: ${int(shuttleTotal)} a weekday, drawn from the commutes of residents within ${sh?.reachM ?? 600} m of an approved shuttle stop. They do not enter mode choice, and they count as transit only in comparisons with the ACS, which records them as bus commuters.</p>
<p>Other home-based tours use NHTS 2017 weekday rates per person for the San Francisco–Oakland CBSA, from its trip chains cut into tours by primary activity ${cite('nhts2017')} (${tab('tours')}): ${fx(TOUR_RATES.shop, 3)} shopping, ${fx(TOUR_RATES.other, 3)} errands and other, and ${fx(TOUR_RATES.social, 3)} social tours. The rates are scaled for youth (${list(Object.entries(PERSON_RATE).map(([p, r]) => `${fx(r.youth, 2)} for ${p === 'other' ? 'errands' : p === 'social' ? 'social trips' : 'shopping'}`))}), seniors (${list(Object.entries(PERSON_RATE).map(([, r]) => fx(r.senior, 2)))}), and other residents (${list(Object.entries(PERSON_RATE).map(([, r]) => fx(r.adult, 2)))}) by the NHTS trip rates of each age group relative to the average person. All are multiplied by a calibrated factor${FX.calibration.tourRateFactor ? ` (${fx(FX.calibration.tourRateFactor, 3)})` : ''} so that residents' trips, stops included, total the linked trips of San Francisco residents in BATS 2023 (${sec('calibration')}). An assumed ${pc(F.calibration.outShare)} of residents' non-work travel goes to external zones instead, in proportion to their commuting ties with the city and discounted by distance.</p>
<p>School tours are made at ${fx(SCHOOL_TRIPS_PER_CHILD / 2, 2)} a weekday per pupil, the NHTS rate of ${fx(NT.school.toursPerPersonWeekday, 3)} school tours per person divided by the ${pc(persons.youth, 1)} of persons aged 5 to 17, an average over all weekdays of the year, school holidays included. Pupils are placed where the ACS counts children enrolled in school, by tract and grade ${cite('acs')}, and each of three levels (to grade 5, grades 6 to 8, and 9 to 12) chooses among its own schools, sized by their 2025–26 enrollment in its grades${sc ? ` (${int(sc.placed)} public, charter, and private schools)` : ''} ${cite('cdeEnroll')}. SFUSD allocates places by citywide choice, lottery, and feeder patterns ${cite('sfusdAssignment')}, and in 2017 ${pc(ST.sfusd.k5Distance2017.mi2plus)} of its elementary pupils lived more than two miles from school ${cite('sfctaSchoolAccess')}, so shadow prices hold every school zone to its enrollment (${sec('destination')}).</p>
<p>College tours are generated at the campuses. IPEDS counts ${int(ST.ipeds.totals.enrolled)} students at the city's colleges in fall 2023, of whom ${int(COLLEGE.inPerson)} took at least one class on campus ${cite('ipeds')}. Each is assumed to come three days a week for a 30-week year ${cite('sfsuSurvey2023', 'sfsuTdm2025')}, or ${fx(COLLEGE.attendance, 3)} tours on an average weekday. City residents make ${pc(ST.sfsu.residence2018.shares['San Francisco'])} of SF State's tours ${cite('sfsuSurvey2018')} and ${pc(COLLEGE.residentShare)} of other campuses' ${cite('ccsfResidence')}, starting where the ACS places college students; the rest start at the external zones.</p>
<p>Once each tour has a mode, stops are added to residents' tours within the city. On a half-tour of purpose ${math('p')} by mode ${math('m')}, a share ${math('\\sigma_{pm} = \\min(0.9,\\ s_p\\, r_m)')} of the direct leg is replaced by two legs through a stop, where ${math('s_p')} is the NHTS share of half-tours with a stop times the stops in such a half (${fx(STOPS_PER_HALF.work, 2)} for work tours) and ${math('r_m')} the NHTS rate of stops per half-tour by the tour's mode relative to all tours: ${fx(stopModeRef('car') ?? 0, 2)} stops per half-tour on car tours, ${fx(stopModeRef('transit') ?? 0, 2)} on transit tours, ${fx(stopModeRef('walk') ?? 0, 2)} on walking tours, and ${fx(stopModeRef('bike') ?? 0, 2)} on cycling tours ${cite('nhts2017')} (${list(Object.entries(STOP_RATE_BY_MODE).filter(([k]) => k !== 'sr' && k !== 'tnc').map(([k, v]) => `${math(`r_{\\text{${k === 'da' ? 'car' : k}}} = ${v}`)}`))}). With probability ${math(`h = ${STOP_NEAR_HOME}`)}, the NHTS share of stops nearer home than the primary destination, the stop is placed around home, and otherwise around the primary destination. From the anchor zone ${math('a')}, a tour of mode class ${math('c')} (car, transit, walk, or bike) stops in zone ${math('s')} with probability</p>
${display('stop', `P(s \\mid a, c) = \\frac{\\exp\\left(\\ln S^{\\text{stop}}_s + \\lambda_c\\, k_{as}\\right)}{\\sum_{s'} \\exp\\left(\\ln S^{\\text{stop}}_{s'} + \\lambda_c\\, k_{as'}\\right)}, \\qquad S^{\\text{stop}}_s = \\sum_{p} \\varpi_p \\frac{S_{ps}}{\\sum_z S_{pz}}`)}
<p>over the zones the tour's mode can reach (within 3 km on foot, 10 km by bike, and for transit tours within 1.5 km on foot or by transit at midday). The size term mixes the destination sizes of shopping, errands, and social trips in the proportions of the purposes of NHTS stops (${list(Object.entries(STOP_MIX).map(([k, v]) => `${k === 'other' ? 'errands' : k} ${fx(v, 2)}`))}), and the distance decay ${math('\\lambda_c')} was calibrated for each mode class to the NHTS mean detour to a stop. Residents' work tours within the city also make ${fx(WORK_SUBTOURS, 3)} subtours per tour from the workplace (lunch and errands), the NHTS rate: from the workplace to a zone drawn from the same stop distribution around it and back, at midday. Subtours of up to 15 minutes' walk are walked. The legs through stops and the subtours are residents' trips with neither end at home; how they choose their modes is described with mode choice.</p>
${table(
  'tours',
  'Tours and stops on weekdays by primary purpose, NHTS 2017, residents of the San Francisco–Oakland CBSA.',
  ['Primary purpose', 'Tours per person', 'Half-tours with a stop', 'Stops per such half', 'Stops nearer home', 'Home to primary, km', 'Detour to a stop, km', 'Sample tours'],
  Object.entries(NT).map(([p, v]) => [PURPOSE_NAME[p] ?? p, fx(v.toursPerPersonWeekday, 3), pc(v.halfToursWithStop), fx(v.stopsPerHalfWithStop, 2), pc(v.stopNearHomeShare), fx(v.meanPrimaryKmDense, 1), fx(v.meanDetourLegKmDense, 1), int(v.tours_sample)]),
  { numeric: [1, 2, 3, 4, 5, 6, 7], wide: true, notes: `Computed by <code>nhts_tours.py</code> from the NHTS 2017 public-use files ${cite('nhts2017')}. Distances are means for residents of tracts with 10,000 or more people per square mile (the NHTS's two densest classes); the detour is the shorter of the two legs through a stop. Work tours also make ${fx(NT.work.workSubtoursPerTour ?? WORK_SUBTOURS, 3)} subtours from the workplace. The model's work tours come from employed residents (${eq('commute')}), not from the rate in the first column.` },
)}
`)}

${section('destination', 'Destination choice', `
<p>All tours and trips except commutes choose a destination zone with a multinomial logit model,</p>
${display('dest', `P(d \\mid o, p) = \\frac{\\exp U_{pod}}{\\sum_{d'} \\exp U_{pod'}}, \\qquad U_{pod} = \\ln S_{pd} + \\lambda\\, LS_{pod} + \\beta^{\\text{dist}}_p\\, f_p(k_{od}) + \\beta^{\\text{near}}_p \\ln \\max(k_{od}, ${NEAR_KM_FLOOR})`)}
<p>where ${math('S_{pd}')} is the size of zone ${math('d')} for purpose ${math('p')}, ${math('LS_{pod}')} the mode-choice logsum of the tour's round trip for the person type concerned (${sec('mode')}), ${math('k_{od}')} the driving distance in km (within a zone, half the square root of its land area), ${math('f_p')} the piecewise-linear shape of distance in TM1's destination choice for the purpose (slopes per mile over 0–1, 1–2, 2–5, 5–15, and 15 or more miles; for shopping and errands, flat within 2 miles), scaled to equal 5 at 5 km ${cite('tm1Code')}, and ${math(`\\lambda = ${DEST_LOGSUM}`)} an assumed logsum coefficient. Because the logsum enters the destination utility, a service change also moves destinations. The size terms are weighted sums of jobs by LODES sector, enrollment, households, and attractions; shopping, for example, uses retail jobs plus a quarter of food service jobs, and school tours use the zone's enrollment in the grades of their level.</p>
<p>Parks enter by area. Their outlines came from the ${int(F.parks.rpdProperties ?? 0)} properties of the San Francisco Recreation and Park Department (${int(F.parks.rpdAcres ?? 0)} acres) ${cite('rpdParks')} and, for the Presidio and the Golden Gate National Recreation Area, from OpenStreetMap ${cite('osm')}; ${int(F.parks.acresInZones)} acres fall inside the land zones. A park's pull is ${math('w\\, A_{\\text{here}}\\, A^{\\gamma - 1}\\, g_k')}, its acreage in the zone times its total acreage ${math('A')} to the power ${math('\\gamma - 1')}, with the weight ${math('w')} and exponent ${math('\\gamma')} calibrated to counted park visits and a further factor ${math('g_k')} for each counted park. Relative to that pull, a park counts an assumed ${PARK_SIZE.social} times for social trips, ${PARK_SIZE.visitor} times for hotel visitors, and ${PARK_SIZE.regional} times for regional visitors.</p>
<p>The log of distance is a term of the Atlanta Regional Commission's CT-RAMP destination choice, beside distance, its square, and its cube (its coefficients on the log run from ${fx(-0.230311, 2)} for eating out to ${fx(-2.5290686, 2)} for escorting) ${cite('activitysimArc')}; a distance below ${fx(NEAR_KM_FLOOR, 1)} km counts as ${fx(NEAR_KM_FLOOR, 1)} km. Without it, a coefficient on ${math('f_p')} alone, fitted to the mean distance, spread trips almost evenly over the nearest two miles, where the number of destinations grows with the area of the ring, and left too few trips next to home. Both ${math('\\beta^{\\text{dist}}_p')} and ${math('\\beta^{\\text{near}}_p')} were calibrated (${sec('calibration')}). School tours use TM1's distance terms for their level instead, in utility per mile over 0–1, 1–2, 2–5, 5–15, and over 15 miles: ${list(SCHOOL_LEVELS[0].dist.map((v) => fx(v, 2)))} for grade school (elementary and middle levels) and ${list(SCHOOL_LEVELS[2].dist.map((v) => fx(v, 2)))} for high school ${cite('asimMtc')}, all multiplied by one scale calibrated to SFUSD's elementary pupils. For school and college tours a shadow price ${math('\\pi_{pd}')} is added to ${math('\\ln S_{pd}')}, moved after each demand pass by ${math('\\ln(T_{pd}/M_{pd})')}, the log of the zone's enrollment (scaled to the modeled total) over its modeled arrivals, as in TM1's shadow pricing.</p>
`)}

${section('mode', 'Mode choice', `
<p>Six modes are available: drive alone (DA), carpool (SR), ride-hail and taxi (TNC), transit, walk, and bike, with shared bikes and scooters inside the bike alternative (${sec('micromobility')}). Their utilities for one direction of travel between zones ${math('o')} and ${math('d')} are</p>
${display('v-auto', `\\begin{aligned}
V_{\\text{DA}} &= \\beta_t\\,(t^{\\text{auto}}_{od} + 1.5\\,(\\tau_o + \\tau_d)) + \\beta_c\\,(c_m m_{od} + \\pi_d + \\text{toll}_{od}) \\\\
V_{\\text{SR}} &= \\alpha_{\\text{SR}} + \\beta_t\\,(t^{\\text{auto}}_{od} + 1.5\\,(\\tau_o + \\tau_d)) + \\beta_c\\,(c_m m_{od} + \\pi_d + \\text{toll}_{od})/${SR_COST_SHARE} \\\\
V_{\\text{TNC}} &= \\alpha_{\\text{TNC}} + \\beta_t\\,(t^{\\text{auto}}_{od} + 1.5\\,w_o) + \\beta_c\\,\\max\\left(${TNC.min},\\ ${TNC.base} + ${TNC.perMile}\\,m_{od} + ${TNC.perMin}\\,t^{\\text{auto}}_{od}\\right)
\\end{aligned}`)}
${display('v-transit', `V_{\\text{T}} = \\alpha_{\\text{T}} + \\beta_t\\, g_{od} + \\phi\\,\\beta_x\\,(b_{od} - 1) + \\beta_c\\, \\rho_q f_{od} + \\beta_D \\min(D_d, 100) + \\min\\left(\\beta_O D_o,\\ ${ORIGIN_DENSITY_CAP}\\,|\\beta_t|\\right)`)}
${display('v-active', `\\begin{aligned}
V_{\\text{W}} &= \\alpha_{\\text{W}} + \\omega \\left(\\beta_{w1} \\min(t^{\\text{w}}, 20) + \\beta_{w2} \\max(t^{\\text{w}} - 20, 0)\\right) + \\delta_{od} \\\\
V_{\\text{B}} &= \\alpha_{\\text{B}} + \\beta_{b1} \\min(t^{\\text{b}}, 30) + \\beta_{b2} \\max(t^{\\text{b}} - 30, 0) + \\delta_{od}
\\end{aligned}`)}
<p>Here ${math('t^{\\text{auto}}')} is the congested driving time in minutes, ${math('\\tau')} TM1's terminal time by area type (${list(TERMINAL_MIN.map((v) => fx(v, 2)))} minutes from regional core to urban), ${math(`c_m = \\$${AUTO_COST_PER_MILE.toFixed(3)}`)} per mile TM1's 2023 auto operating cost in 2025 dollars, ${math('m')} miles, ${math('\\pi_d')} parking (eight hours at the long-term rate for commutes, an assumed stay at the short-term rate otherwise; long-term rates ${list(PARKING_LONG.map((v) => money(v)))} and short-term ${list(PARKING_SHORT.map((v) => money(v)))} per hour by area type), ${math('w_o')} the ride-hail wait by density (TM1, ${fx(TNC_WAIT_MIN[TNC_WAIT_MIN.length - 1], 1)} to ${fx(TNC_WAIT_MIN[0], 1)} minutes), ${math('g_{od}')} the transit perceived time from the skims (${sec('assignment')}), ${math('b_{od}')} the expected boardings, ${math('f_{od}')} the adult fare, ${math('\\rho_q')} the fare multiple of person type ${math('q')} (${sec('fares')}), and ${math('D')} the density index; ${math('\\delta_{od}')} is the same density adjustment as in the transit utility. Walking is available up to 6 km and cycling up to 20 km, within the city. Transfers are weighted by a calibrated factor ${math('\\phi')}, and the minutes of walking all the way by a calibrated factor ${math('\\omega')}; the walk to and from transit keeps TM1's weights.</p>
<p>The coefficients are TM1's trip-level values ${cite('tm1Code')} (${tab('coef')}). The cost coefficient of each income group (${sec('population')}) follows TM1's relation between cost, time, and value of time,</p>
${display('cost', `\\beta_c = \\frac{60\\,\\beta_t}{\\text{VOT}} \\ \\text{per dollar}, \\qquad \\text{VOT}_{oc} = \\left(\\sum_{k \\in c} \\frac{s_{ok}}{\\text{VOT}_k}\\right)^{-1}`)}
<p>where ${math('s_{ok}')} is the share of income band ${math('k')} among the zone's households of class ${math('c')}, and the values of time of the four bands (under $50,000, $50,000 to $100,000, $100,000 to $200,000, and $200,000 or more) are ${list(VOT_BY_INCOME.map((v) => money(v, 2)))} per hour, TM1's lognormal means for its four income classes in 2000 dollars inflated by MTC's factor of 1.98. The harmonic mean keeps each class's cost sensitivity equal to that of its households. Travelers whose income the model does not know, in-commuters and regional visitors, use ${money(VOT_TYPICAL, 2)} per hour; hotel visitors and air travelers use ${money(VOT_VISITOR, 2)}, the top band's. The modes are grouped into a nested logit with an auto nest (DA, SR) and a non-motorized nest (walk, bike); transit and TNC sit alone under the root:</p>
${display('nl', `P_m = \\frac{e^{I_{n(m)}}}{\\sum_{n'} e^{I_{n'}}}\\cdot\\frac{e^{V_m/\\mu}}{\\sum_{j \\in n(m)} e^{V_j/\\mu}}, \\qquad I_n = \\mu \\ln \\sum_{j\\in n} e^{V_j/\\mu}, \\qquad LS = \\ln \\sum_n e^{I_n}`)}
<p>with ${math(`\\mu = ${NEST}`)}, TM1's upper-level nesting coefficient; TM1's deeper tree (auto submodes at 0.35, transit at 0.5) is reduced to one level.</p>
<p>A resident's home-based tour chooses a mode, and its trips then choose their own modes among those the tour's mode allows, as in TM1, where trip mode choice is conditional on the tour mode ${cite('tm1Code')}. The tour's mode is the mode of its trip into the primary destination, which is how the NHTS tours the trips are fitted to are read; the trip back and the trips through stops choose. The tour's utilities are those of TM1's tour mode choice model (ModeChoice.xls), applied to each leg: in-vehicle time is worth ${fx(TOUR_COEFFS.work!.ivt, 4)} a minute on work tours, ${fx(TOUR_COEFFS.school!.ivt, 4)} on school and college tours, and ${fx(TOUR_COEFFS.shop!.ivt, 4)} on the others, and a transfer costs ${fx(TOUR_COEFFS.work!.xfer / TOUR_COEFFS.work!.ivt, 0)} in-vehicle minutes. The leg out enters the tour's utility by the tour's mode, and the leg back through the logsum of its trip's mode choice:</p>
${display('roundtrip', `V_M = V_{M,\\text{out}} + \\theta \\ln \\sum_{m \\in A(M)} \\exp\\!\\left(\\frac{V_{m,\\text{back}}}{\\theta} + K_{Mm}\\right) + \\eta_{M}, \\qquad P(m \\mid M) = \\frac{\\exp(V_{m,\\text{back}}/\\theta + K_{Mm})}{\\sum_{j \\in A(M)} \\exp(V_{j,\\text{back}}/\\theta + K_{Mj})}`)}
<p>where ${math('A(M)')} is the set of modes a tour by mode ${math('M')} allows (${tab('tripmodes')}) and ${math('K_{Mm}')} the trips' constants, with ${math('K_{MM} = 0')}. A tour whose mode offers a better way back is worth more than its own mode alone (a transit tour can come home by ride-hail when the last buses are sparse). Letting the leg out choose as well was tested and rejected: calibrated, it reached a degenerate fit in which walking tours carried transit riders and the transit tours' constants fell without bound. The scale ${math('\\theta')} is TM1's tour in-vehicle coefficient over its trip one (${list([['work', 'work'], ['shop', 'the non-mandatory purposes'], ['school', 'school and college']].map(([p, w]) => `${fx(TOUR_COEFFS[p as 'work']!.ivt / COEFFS[p as 'work'].ivt, 2)} for ${w}`))}), held at ${NEST} for school and college tours so that the trips' choice is at least as sharp as the nests'. The trips choose at the value of time of the home zone's mix of incomes, and the leg back's money enters the tour at its trips' expected cost. Destination choice (${eq('dest')}) sees the logsum over the tour modes.</p>
<p>Each leg carries half the parking charge and sees the service of the periods in which it travels, its level of service averaged over the four assignment periods by that direction's time-of-day shares (${sec('tod')}): a commute's leg to work is ${pc(LEG_SHARES.work.out.AM, 0)} in the morning peak, and ${pc(LEG_SHARES.social.back.NT, 0)} of social tours come home at night. Transit is averaged only over the periods in which it connects the two zones, and its utility gains the log of the share of legs that travel in them. Stops do not enter the tour's choice. The term ${math('\\eta_{M}')} holds the tour's constants: those of its purpose and car-ownership group and, for transit, a constant for the home neighborhood and, for commutes that cross the city line, one for the county at the other end (${sec('calibration')}). In-commuters' tours keep one mode for both legs. The trips of in-commuters and visitors with neither end at home, and the trips of hotel visitors, air travelers, and regional visitors, choose a mode trip by trip with TM1's trip coefficients.</p>
<p>${tab('tripmodes')} lists the modes each tour mode allows. A car tour's trips stay in a car, since the car has to come home, though a carpool passenger may walk a leg, as TM1 allows. TM1 allows a walk tour only ride-hail, but in the NHTS ${pc(nhtsTrip.walk.toursWithATripBy.transit ?? 0, 0)} of the tours that walked to their primary destination rode transit on another trip ${cite('nhts2017')}, so the model allows it; of the tours that rode transit there, ${pc(nhtsTrip.transit.toursWithAnotherMode, 0)} used another mode on at least one trip. The constants were fitted to these NHTS shares; the ride-hail tours' rest on only ${nhtsTrip.tnc?.tours_sample ?? 0} sampled tours.</p>
<p>The legs through stops (${sec('tours')}) choose their modes as the trip back does, conditional on the tour's mode, except the leg into the primary destination on the way out, which is by the tour's mode. They use TM1's non-mandatory tour utilities at their trip scale (${math('\\theta')} = ${fx(tripScale(TOUR_COEFFS.shop!.ivt, COEFFS.shop.ivt), 2)}) for an adult at ${money(VOT_TYPICAL, 2)} an hour, so a transit commuter who stops at a shop two blocks from home walks that leg. Transit tours' stop legs keep their tour's period; walk and ride-hail tours' travel at the non-work tours' mix of periods, and car and bike tours' are costed at midday. Work-based subtours longer than a 15-minute walk choose the same way, at midday.</p>
${tripModeTable((F.calibration as { tripSwitch?: Record<string, number> }).tripSwitch)}
${table(
  'coef',
  'Mode choice coefficients (per minute of time, per transfer).',
  ['Purpose', 'In-vehicle time β<sub>t</sub>', 'Walk ≤ 20 min', 'Walk > 20 min', 'Bike ≤ 30 min', 'Bike > 30 min', 'Transfer β<sub>x</sub>', 'Cost per $ at $19.00/h'],
  [
    ['Commute', fx(cw.ivt, 4), fx(cw.walkShort, 4), fx(cw.walkLong, 4), fx(cw.bikeShort, 4), fx(cw.bikeLong, 4), fx(cw.xfer, 3), cc(cw.ivt, VOT_TYPICAL)],
    ['School and college', fx(cs.ivt, 4), fx(cs.walkShort, 4), fx(cs.walkLong, 4), fx(cs.bikeShort, 4), fx(cs.bikeLong, 4), fx(cs.xfer, 3), cc(cs.ivt, VOT_TYPICAL)],
    ['All other purposes', fx(co.ivt, 4), fx(co.walkShort, 4), fx(co.walkLong, 4), fx(co.bikeShort, 4), fx(co.bikeLong, 4), fx(co.xfer, 3), cc(co.ivt, VOT_TYPICAL)],
  ],
  { numeric: [1, 2, 3, 4, 5, 6, 7], wide: true, notes: `Source: TM1 TripModeChoice.xls ${cite('tm1Code')}. Walk, bike, and transfer coefficients are TM1's multiples of the in-vehicle coefficient (2 and 10; 4 and 20; 15). The destination density coefficient is ${fx(-0.2, 1)} β<sub>t</sub> and the origin density coefficient ${fx(-0.6, 1)} β<sub>t</sub>, capped at ${ORIGIN_DENSITY_CAP} minutes. The FHWA manual cites FTA guidance of −0.02 to −0.03 for the in-vehicle coefficient of home-based work trips ${cite(['fhwa2010', 'p. 7-15'])}.` },
)}
`)}

${section('tod', 'Time of day', `
<p>The day is divided into TM1's five periods: early morning (${hh(PERIOD_BOUNDS.EA[0])} to ${hh(PERIOD_BOUNDS.EA[1])}), morning peak (to ${hh(PERIOD_BOUNDS.AM[1])}), midday (to ${hh(PERIOD_BOUNDS.MD[1])}), evening peak (to ${hh(PERIOD_BOUNDS.PM[1])}), and evening (to ${hh(PERIOD_BOUNDS.EV[1])}). Each purpose's trips are split across periods, and within each period into the direction leaving home and the direction returning, by shares computed from the 2017 NHTS for the San Francisco–Oakland CBSA ${cite('nhts2017')}; SF-CHAMP's visitor model supplies the visitors' shares ${cite('sfchampDocs')}. For assignment, the evening and early morning are combined into one night period, giving four assignment periods of ${list(Object.entries(TPERIOD_HOURS).map(([p, h]) => `${h} hours (${p})`))}, and transit skims are computed for all four.</p>
<p>A zone pair's transit trips are not split by the purpose's shares alone, since transit is less likely for a leg that travels when service is slower or sparser. Each period's share of a direction is multiplied by transit's probability with the leg in that period, ${math('1/\\left[1 + (1/P - 1)\\,e^{-\\nu\\Delta}\\right]')}, where ${math('P')} is the probability of a transit tour where both legs have service, ${math('\\Delta')} the difference between that period's transit utility and the direction's mix, less the same difference in driving times driving's share of the other modes, and ${math('\\nu')} the leg's weight in the utility (one for a tour or a one-way trip, one half for trips that average their two directions), a first-order approximation. The shares are then rescaled so that each direction keeps its trips, and a period without service gets none.</p>
`)}

${section('assignment', 'Transit assignment by optimal strategies', `
<p>Transit riders are assigned by the optimal strategies method of Spiess and Florian ${cite('spiess')}, the headway-based assignment used in TM2. At a stop the rider has a set of attractive lines and boards one of them. The graph has, for each stop, a boarding node and an alighting node, and, for each line, one node per stop served, so every path boards at least once and transfers are counted exactly. Line frequencies are the scheduled trips in each period. At night (7 p.m. to 6 a.m.), the frequency riders see blends the trips leaving before and after midnight, weighted by the shares of night trips that start in each, ${pc(1 - OWL_SHARE, 1)} and ${pc(OWL_SHARE, 1)} in the 2017 NHTS ${cite('nhts2017')}; all of the night's trips count for capacity. A route that runs only after midnight therefore serves only the late share of night riders${night ? ` (${nw(night.owlOnlyPatterns)} of the ${int(night.patternsWithEvening)} night-period patterns)` : ''}.</p>
<p>Buses that bunch make riders wait longer than half the scheduled headway. Each Muni route's wait factor ${math('w_r')}, the expected wait of a rider arriving at random over half the scheduled headway, was measured from realtime arrivals on one weekday${rel?.day ? `, ${ymd(rel.day)}` : ''}, using Cal-ITP's stop time metrics from the 511 GTFS-Realtime feed ${cite('calitp')}: with ${math('x')} the actual headway at a stop over the scheduled one, ${math('w_r = \\mathrm{E}[x^2]/\\mathrm{E}[x]')}, which equals ${math('1 + \\mathrm{CV}^2')} when buses keep their scheduled mean headway.${rel ? ` Factors were measured for ${rel.routesMeasured} routes${rel.bounds ? `, bounded at ${fx(rel.bounds[0], 1)} and ${fx(rel.bounds[1], 1)}` : ''}, with a morning-peak median of ${rel.median.AM !== null && rel.median.AM !== undefined ? fx(rel.median.AM, 2) : '–'}.` : ''} Routes not measured take their mode's median, and the cable cars 1; the afternoon was measured from 3 to 4:30 p.m. only, because the later records conflict. Riders setting out for a stop with a long headway are assumed to time their arrival, so headways above ${PATH.timedHeadway} minutes count half beyond that point, following the UK Department for Transport's guidance for the first boarding ${cite('tagM32')} and the effective headways of Toronto's GTAModel ${cite('tmgToolbox')}. A rider changing from another line cannot time the connection, so transfers board from a separate node and wait the full ${math('w_r h')}:</p>
${display('headway', `\\tilde h = \\begin{cases} w_r\\, h & h \\le ${PATH.timedHeadway} \\\\ w_r \\cdot ${PATH.timedHeadway} + \\tfrac12 (h - ${PATH.timedHeadway}) & h > ${PATH.timedHeadway} \\end{cases}, \\qquad f = 1/\\tilde h`)}
<p>Riders of ${list(Object.keys(HEADWAY_FRACTION).map((k) => (k === 'ferry' ? 'the ferries' : MODE_NAME[k] ?? k)))}, which run to a timetable riders plan around, wait ${pc(Object.values(HEADWAY_FRACTION)[0])} of the headway instead of half, as in TM2 ${cite('tm2py')}. Labels are computed backward from each destination. At a boarding node ${math('i')} with attractive line set ${math('\\bar A_i')}, the expected cost to the destination is</p>
${display('strategy', `u_i = \\frac{\\tfrac{1}{2}\\,\\omega_{\\text{wait}} + \\sum_{a \\in \\bar A_i} f_a\\,(c_a + u_{j(a)})}{\\sum_{a \\in \\bar A_i} f_a}`)}
<p>where ${math('c_a + u_{j(a)}')} is the cost of riding line ${math('a')} onward and the wait, half the combined headway, is weighted by ${math(`\\omega_{\\text{wait}} = ${PATH.waitWeight}`)}. Lines are taken in increasing order of ${math('c_a + u_{j(a)}')} and join the set while that cost is below the current ${math('u_i')}. In optimal strategies the rider boards whichever attractive line comes first. Muni shows predicted arrivals at its shelters and in apps, so an informed rider instead sees each line's wait and boards the one with the least perceived cost, ${math('\\omega_{\\text{wait}} w_a + c_a + u_{j(a)}')}, the route choice with online information of Gentile, Nguyen, and Pallottino ${cite('gentile2005')}.${op ? ` Muni's predictions 10 minutes ahead were off by ${fx(op.predictions.sd10 / 60, 1)} minutes (standard deviation) ${cite('calitpPredictions')}, which in a simulation of two-line stops keeps ${pc(op.predictions.retained)} of the gain exact knowledge of the waits would bring, and ${pc(op.predictions.consulting)} of riders in SFMTA's 2018 survey checked predictions at least sometimes ${cite('sfmtaInfo2018')}.` : ''} A share ${math(`\\lambda = ${PATH.informedShare}`)} of riders therefore choose as informed riders${op ? ` (${fx(op.predictions.retained, 2)} × ${fx(op.predictions.consulting, 2)})` : ''}, and the rest board whichever line of the optimal-strategy set comes first.</p>
<p>Ride links cost the running time times the mode's perception factor and the crowding factor below, plus any distance fare, with fares converted at ${money(PATH.votPerMin * 60)} per hour. The boarding fares of Muni, BART, and Caltrain are carried on the access and transfer links by which a rider enters them, and the alighting links carry the per-ride fares of the other operators, the calibrated mode biases, and the per-ride part of the reliability term. A change of lines costs ${fx(xferMin, 1)} minutes plus twice any walking time: the weight mode choice gives a change on a home-based tour, TM1's ${fx(TOUR_COEFFS.work!.xfer / TOUR_COEFFS.work!.ivt, 0)} in-vehicle minutes, times the calibrated transfer factor (${fx(FX.calibration.xferFactor ?? 1, 2)}), which is fitted to the share of Muni boardings that follow another vehicle in SFMTA's 2017 on-board survey (${sec('calibration')}). A rider thus weighs a change the same way in choosing a route as in choosing transit. TM1's own path builder charges 20 minutes for a second boarding ${cite('tm1Code')}. ${tab('path')} lists the weights.</p>
<p>A block group is often wide enough to hold two parallel bus lines, so access is chosen point by point. Each point ${math('k')} of zone ${math('o')} (a census block, weighted by residents and jobs, ${math('w_k')}) has its own walk ${math('t_{ks}')} to each stop ${math('s')} within reach, and its riders spread over those stops by a logit on the walk and the cost onward:</p>
${display('access', `p_{s \\mid k} = \\frac{e^{-\\theta\\,(\\omega_{\\text{walk}} t_{ks} + u_s)}}{\\sum_{s'} e^{-\\theta\\,(\\omega_{\\text{walk}} t_{ks'} + u_{s'})}}, \\qquad p_{os} = \\frac{1}{\\pi_o} \\sum_{k} w_k\\, p_{s \\mid k}`)}
<p>with ${math(`\\theta = ${PATH.accessTheta}`)} per perceived minute, set before any comparison with counts and not fitted, where the sum is over the points within reach of some stop and ${math('\\pi_o')} is their share of the zone. The zone's cost is its points' mean logsum plus ${math('-\\tfrac{1}{\\theta} \\ln \\pi_o')}, TM1's walk-access share, so a zone that transit reaches only in part pays for the rest. Getting off is chosen the same way: a rider on a line at node ${math('i')} bound for point ${math('k')} of zone ${math('d')} gets off at stop ${math('s')} with probability</p>
${display('egress', `p_{s \\mid ik} = \\frac{e^{-\\theta\\,(c_{is} + \\omega_{\\text{walk}} t_{sk})}}{\\sum_{s'} e^{-\\theta\\,(c_{is'} + \\omega_{\\text{walk}} t_{s'k})}}`)}
<p>where ${math('c_{is}')} is the cost of riding on from ${math('i')} to ${math('s')} and getting off there. Riding on or getting off, stop by stop, is a recursive logit ${cite('fosgerau2013')}, exact along each line, and its logsum enters the strategy at every line node as one more option beside riding on to change lines. A zone is thus the aggregate of its points at both ends of a trip, in the sense of the aggregation of elemental alternatives ${cite('benAkiva1985')}, with the walk-access share of TM1 and STOPS ${cite('tm1Code', 'stopsGuide')} for the part beyond reach.</p>
${PATH.transferLogit ? `<p>Where to change lines is chosen the same way, so that where two lines share several stations the change spreads over them rather than piling up at the single stop best for the strategy. A rider arriving at a stop compares getting off there to change, at the cost ${math('T_s')} of the strategy onward from the stop, with riding on to the next stop and choosing again:</p>
${display('xfer', `W_s = -\\tfrac{1}{\\theta} \\ln\\left(e^{-\\theta\\, T_s} + e^{-\\theta\\,(c_{s,s+1} + W_{s+1})}\\right), \\qquad p_{\\text{off} \\mid s} = e^{-\\theta\\,(T_s - W_s)}`)}
<p>with the same ${math('\\theta')}, again a recursive logit ${cite('fosgerau2013')} that splits flow inside the optimal strategy as a hyperpath splits it at its nodes ${cite('nguyen1988')}. Getting off to board the same line again, or a line that runs on with it to its next stop, is not counted as a change. The onward costs ${math('T_s')} come from a first search without this choice, so trips that change twice are approximated.</p>
` : ''}<p>Underground stations add an assumed street-to-platform time from each station's depth (0.5 to 2 minutes; 1.25 at BART's four downtown stations), and their walks are measured from their mapped entrances ${cite('osm')}. A change between BART and Muni Metro inside a shared station costs the two platform times and no walk on the street. A fit of the platform times to BART's counts was built but is not used, so that those counts remain a test. The transit skims used by mode choice are the expected values of each component over the strategy, combined as</p>
${display('skim', `g_{od} = \\mathrm{E}\\left[\\textstyle\\sum \\psi_m\\, \\kappa\\, t^{\\text{ivt}}\\right] + ${PATH.waitWeight}\\,\\mathrm{E}[t^{\\text{wait}}] + ${PATH.walkWeight}\\,\\mathrm{E}[t^{\\text{walk}}] + \\mathrm{E}[\\text{bias}]`)}
<p>with the expected boardings ${math('b_{od}')} and fare ${math('f_{od}')} carried separately into ${eq('v-transit')}.</p>
<p>Three adjustments take the network as operated. First, each Muni route's ride times are scaled by its ratio of observed to scheduled running time in the period, from the same realtime arrivals ${cite('calitp')}, shrunk toward its mode's by the hours observed.${op && allRun ? ` Systemwide, Muni ran within ${pc(Math.max(Math.abs(allRun[0] - 1), Math.abs(allRun[1] - 1)), 0)} of its schedule in every period${metroRun ? `, Muni Metro ${pc(metroRun[0] - 1, 0)} to ${pc(metroRun[1] - 1, 0)} slower` : ''}.` : ''} Second, scheduled trips that do not run lower the frequency riders see and the capacity they share.${op ? ` Each route's share of trips missing from the realtime feed was scaled so that the system delivers SFMTA's ${pc(1 - op.notRun.sfmta12m, 1)} of scheduled service hours over the year to June 2026 ${cite('sfmtaDelivered')}; the median route loses ${pc(op.notRun.medianRoute, 1)} of its trips.` : ''} Third, the spread of travel times enters the cost of a ride. The ratio sets a route's total, not where along the route the time goes. Between its timepoints a timetable spreads time by distance, so a slow downtown block gets about the same time per meter as a fast outer one. Each Muni line's time in a period is therefore spread over its stop-to-stop hops in proportion to the median time vehicles took on each over 15 weekdays in September and October 2025 ${cite('calitpSpeeds')} (at least 20 runs a hop), keeping the period's total, wherever observed hops cover at least 80% of it. Unreliability, the variation riders cannot predict ${cite('tagA13')}, was measured as the day-to-day standard deviation of the same scheduled trip's running time between the same two stops over 15 weekdays in autumn 2025 ${cite('calitpSpeeds')}.${op?.sd.bus ? ` For Muni buses it is ${math(`\\sigma = ${fx(op.sd.bus.a, 2)} + ${fx(op.sd.bus.b, 3)}\\,t`)} minutes for ${math('t')} minutes aboard, with Muni Metro, the T, and rapid and express buses fitted separately and each route scaled from its own runs.` : ''} BART, Caltrain, and the ferries publish only on-time shares ${cite('bartOtp', 'caltrainOtp', 'sfbfOtp')}${op ? `; with delays zero on most rides and exponential beyond the timetable, these give a mean lateness and a standard deviation per ride of ${fx(op.rail.bart.meanLateMin, 2)} and ${fx(op.rail.bart.sdMin, 1)} minutes for BART, ${fx(op.rail.caltrain.meanLateMin, 2)} and ${fx(op.rail.caltrain.sdMin, 1)} for Caltrain, and ${fx(op.rail.ferry.meanLateMin, 2)} and ${fx(op.rail.ferry.sdMin, 1)} for the ferries, and the mean lateness is added to the ride time` : ''}. Other operators' buses take Muni's spreads, and a new line takes its mode's medians.</p>
<p>Each minute of standard deviation costs ${math(`\\rho = ${PATH.reliabilityRatio}`)} in-vehicle minutes, the reliability ratio that RAND Europe's 2004 expert workshop set for bus and train ${cite('shrp2L17')}; Sweden's ASEK uses 1.1 for urban transit, and most estimates reviewed by Carrion and Levinson fall between 0.7 and 1.5 ${cite('carrion2012')}. UK guidance values the lateness of timetabled services instead ${cite('tagA13', 'batley2019')}. Spreads add ride by ride, an upper bound on a trip's standard deviation. The term enters route choice but not mode choice, since TM1's mode-choice coefficients were estimated without a reliability term and already carry transit's usual unreliability; added to mode choice in a test, it lowered Muni's boardings by 9% and worsened the route-level fit.</p>
${table(
  'path',
  'Transit path choice parameters.',
  ['Parameter', 'Value', 'Source'],
  [
    ['Wait time weight', fx(PATH.waitWeight, 1), `TM1 transit skims ${cite('tm1Code')}`],
    ['Walk time weight (access, egress, transfer)', fx(PATH.walkWeight, 1), 'TM1 transit skims'],
    ['Transfer penalty', `${fx(xferMin, 1)} min`, `mode choice's weight on a change on a tour (TM1's 30 minutes times the calibrated factor); published values 4–20 min, TM1's path builder 20`],
    ['Headway counted in full up to (first boarding)', `${PATH.timedHeadway} min`, 'UK TAG M3.2; Toronto GTAModel'],
    ['Wait as a share of the headway, Caltrain and ferries', fx(Object.values(HEADWAY_FRACTION)[0], 1), 'TM2 (tm2py)'],
    ['Wait factor, Muni routes', rel?.bounds ? `${fx(rel.bounds[0], 1)} to ${fx(rel.bounds[1], 1)}` : 'by route', `Measured, realtime arrivals ${cite('calitp')}`],
    ['Share of riders choosing on predicted arrivals', fx(PATH.informedShare, 2), `Measured prediction error ${cite('calitpPredictions')}; SFMTA survey ${cite('sfmtaInfo2018')}`],
    ['Running time, Muni', 'observed ÷ scheduled, by route and period', `Measured, realtime arrivals ${cite('calitp')}`],
    ['Trips run, Muni', 'share of scheduled, by route and period', `Measured; scaled to SFMTA ${cite('sfmtaDelivered')}`],
    ['Reliability ratio (per minute of SD of ride time)', fx(PATH.reliabilityRatio, 1), `RAND Europe 2004, in SHRP 2 L17 ${cite('shrp2L17')}`],
    ['Perceived in-vehicle time factor', Object.entries(IVT_FACTOR).filter(([, v]) => v !== 1).map(([k, v]) => `${MODE_NAME[k] ?? k} ${FX.calibration.ivtFactor?.[k] !== undefined ? `${fx(FX.calibration.ivtFactor[k]!, 2)} (calibrated)` : v}`).join(', ') + '; buses 1.0', `TM1 trip mode choice${Object.keys(FX.calibration.ivtFactor ?? {}).length ? `; ${list(Object.keys(FX.calibration.ivtFactor ?? {}).map((k) => MODE_NAME[k] ?? k))} calibrated` : ''}`],
    ['Value of time for fares in path choice', `${money(PATH.votPerMin * 60)}/h`, 'Assumed'],
    ['Access spread θ', `${PATH.accessTheta} per min`, 'Assumed, not fitted'],
    ['Crowding, seated weight', `${CROWDING.minSeat} to ${CROWDING.maxSeat}, power ${CROWDING.powSeat}`, 'TM2 (tm2py)'],
    ['Crowding, standing weight', `${CROWDING.minStand} to ${CROWDING.maxStand}, power ${CROWDING.powStand}`, 'TM2 (tm2py)'],
    ['Load met by the average rider, relative to the period mean', list(Object.entries(ls).filter(([, v]) => v !== 1).map(([p, v]) => `${p} ${fx(v, 3)}`)), 'BART hourly counts and Muni timetable'],
  ],
)}
<p>After each assignment, the load ${math('V')} on every link of every line is compared with the line's capacity over the period, ${math('C')} places and ${math('S')} seats per vehicle times its trips. Capacities are MTC's and SFMTA's ${cite('tm1Code', 'sfmtaSrtp')}: 63 riders (39 seated) on a 40-foot bus, 94 (56) on a 60-foot bus, 119 (60) on a light-rail car, 1,110 (550) on a ten-car BART train, and 1,502 (681) on a seven-car Caltrain set, with each Muni route's mix of bus lengths observed in June 2026 ${cite('calitpVehicles')} and the ferries' licensed passengers, ${CAPACITY_FERRY} ${cite('ferryFleets')}. Riders are not spread evenly over a period, so the load the average rider meets is multiplied by ${math('\\ell_p = \\sum_h r_h^2 / s_h')}, where ${math('r_h')} is the share of the period's riders traveling in hour ${math('h')} (from BART's October 2025 weekday entries and exits at the city's stations ${cite('bartRidership')}) and ${math('s_h')} the share of its Muni trips scheduled then: ${list(Object.entries(ls).map(([p, v]) => `${fx(v, 3)} in the ${p} period`))}${ph.AM ? ` (in the morning peak, ${pc(ph.AM.riderShare)} of the period's riders travel in the ${hh(ph.AM.peakHour)} hour, which has ${pc(ph.AM.serviceShare)} of the service)` : ''}. The in-vehicle time of the next pass is multiplied by TM2's crowding factor ${cite('tm2py')}, a weighted average of a seated and a standing discomfort weight, each rising with the volume to capacity ratio ${math('x = \\ell_p V/C')}:</p>
${display('crowd', `\\kappa(V) = \\max\\left\\{1,\\ \\frac{w_s(x)\\,\\min(V,S) + w_{st}(x)\\,\\max(V-S,0)}{V}\\right\\},\\quad w_s = ${CROWDING.minSeat} + ${fx(CROWDING.maxSeat - CROWDING.minSeat, 1)}\\,x^{${CROWDING.powSeat}},\\quad w_{st} = ${CROWDING.minStand} + ${fx(CROWDING.maxStand - CROWDING.minStand, 1)}\\,x^{${CROWDING.powStand}}`)}
<p>with ${math('V')} the adjusted load. The crowding factor makes a full vehicle unpleasant but turns no one away, so boarding is also limited, following the frequency-based assignment with strict capacities of Cepeda, Cominetti, and Florian ${cite('cepeda2006')}. For each line at each stop and in each hour ${math('h')} of the period, the riders wanting to board, ${math('v\\,r_h')}, are compared with the room left by the riders already aboard, ${math('K s_h - \\tilde v\\,r_h')}, where ${math('K')} is the period's capacity and ${math('\\tilde v')} the riders staying on through the stop. A rider fails to board a given vehicle with probability</p>
${display('fail', `\\pi_h = \\min\\left\\{1,\\ \\left(\\frac{v\\,r_h}{K s_h - \\tilde v\\,r_h}\\right)^{\\beta}\\right\\},\\quad \\beta = ${CAPACITY.beta}`)}
<p>and, having failed, waits a full headway for the next vehicle, so expects ${math('\\pi_h/(1-\\pi_h)')} extra headways, with ${math('1-\\pi_h')} kept at ${fx(CAPACITY.minAvail, 1)} or more. Averaged over the period's riders, this extra wait ${math('E')} sets an availability ${math('a = 1/(1+E)')}, and in the next pass the wait on the boarding link becomes ${math('1/(2f) + (1/a - 1)/f_0')}, with ${math('f')} the effective frequency and ${math('1/f_0')} the scheduled headway. The exponent is assumed: about 1% of riders fail to board when they would fill a third of the room, 6% at half, and 41% at four-fifths. Emme, as used in TM2 and CMAP's model, raises the headway instead ${cite('tm2py', 'cmapTransit')}; UK TAG names failure to board as the second effect of crowding ${cite(['tagM32', '§3.6.2'])}.</p>
${CAP ? capacityResults() : ''}
<p>BART and Caltrain also carry riders whose trips have no end in the city (between Palo Alto and San Jose, between Oakland and Berkeley, or through the city to the Peninsula). These background riders are added to ${math('V')} as a fixed load on each hop of each BART and Caltrain pattern, by period. It comes from BART's August 2026 station-to-station counts, by period from its hourly data ${cite('bartRidership')}, and from Caltrain's 2024 origin–destination matrix ${cite('caltrainOD2024')} fitted to its FY2026 station boardings ${cite('caltrainRidership')}, with periods from its 2025 surveys ${cite('caltrainTriennial2025', 'caltrainCss2025')}, less the model's own journeys between the same stations. Background riders count in crowding and in the loads reported, never in boardings or the calibration targets. In a scenario they respond only to service: a pattern's background riders change with its trips by a frequency elasticity of ${BACKGROUND_FREQ_ELASTICITY} ${cite(['tcrp95c9', 'p. 9-4'])}, and a pattern removed hands its riders to the patterns still serving the same stations.</p>
`)}

${roads()}

${microModel()}

${section('special', 'Visitors, special generators, and conditions', `
<p>Non-residents' travel has its own generators. In-commuters' work tours come from the census flows (${sec('tours')}). In-commuters at work also make 0.8 trips with neither end at home and hotel visitors one, produced in proportion to jobs, to retail and food service jobs, and to population, with their own destination and mode choice. Hotel visitors were estimated from ${int(HOTEL_ROOMS_SF)} rooms, an approximate city total attributed to San Francisco Travel, at ${fx(VISITORS_PER_ROOM, 2)} visitors per room (SF-CHAMP's party size times an assumed occupancy) making ${VISITOR_TRIPS} trips a day ${cite('sfchampDocs')}, located by the rooms of OpenStreetMap hotels${F.totals.hotelRoomsOsm ? ` (which add up to ${int(F.totals.hotelRoomsOsm)} rooms; only their distribution was used)` : ''}. Air travelers between the city and SFO are assumed to make ${int(F.calibration.airportTrips)} trips a day. Regional visitors (non-residents traveling to the city for purposes other than work) are generated at each external zone in proportion to its in-commuters, at a rate calibrated to BART exits in the city (${sec('calibration')}).</p>
<p>Most riders of the cable cars and the historic streetcars ride for the ride itself, which a destination choice model does not represent, so, as in SF-CHAMP's visitor model, these rides are a separate generator ${cite('sfchampDocs')}. SFMTA has not counted these routes since 2020, so the daily rides were set at an assumed 80% of their 2019 average weekday boardings ${cite('sfmtaRidership')}, less what the model already carries on them as ordinary trips: ${list(Object.entries(tr).map(([k, v]) => `${TOUR[k] ?? k} ${int(v)}`))}. The rides are loaded end to end on each pattern of the route in proportion to its service and spread over the day like visitor trips. The large parks with counted visits get their own factor in the destination size term (${sec('destination')}).</p>
<p>Crowds at the city's large venues are a third generator. Every weekday event from ${ymd(EVR.period.from)} to ${ymd(EVR.period.to)}, the months of the Muni counts, was listed with its attendance: Giants games ${cite('bbrefGiants')}, Warriors and Valkyries games ${cite('bbrefWarriors')}, concerts and other events at Chase Center, Oracle Park, and Bill Graham Civic Auditorium (attendance assumed by kind of event) ${cite('eventListings')}, and the ${nw(EVR.conventions.length)} largest conventions at Moscone ${cite('conventions')}. An average weekday has ${int(EA.all)} attendees: ${list([`${int(EA.giants)} at Giants games`, `${int(EA.warriors)} at Warriors games`, `${int(EA.valkyries)} at Valkyries games`, `${int(EA.chaseOther)} at Chase Center's other events`, `${int(EA.moscone)} at Moscone`, `${int(EA.billGraham)} at Bill Graham`, `${int(EA.oracleOther)} at Oracle Park concerts`])}.</p>
<p>Where attendees live follows the Warriors' arena environmental report, from the team's market study and a survey of season-ticket holders ${cite('gswSeir')}: ${pc(sfShare / 100)} in the city, ${pc(EO.east / 100)} in the East Bay, ${pc(EO.south / 100)} on the Peninsula and in the South Bay, ${pc(EO.north / 100)} in the North Bay, and ${pc(EO.hotel / 100)} from outside the region, taken here to stay in hotels. Oracle Park and Bill Graham take the same distribution, and conventioneers the report's convention distribution. As at Pacific Bell Park's first season, ${pc(EF.evening.sf / 0.825)} of fans at weeknight games come directly from work ${cite('fhwaPacBell')}. Night games start at 7 p.m. and concerts at 8 p.m. Attendees choose a mode with the constants of their own kind of traveler and pay ${money(EVENT_PARKING, 0)} to park. A transit constant for Oracle Park and one for Chase Center were fitted to their transit shares, 45% of trips to weekday Giants games in the team's 2012 survey ${cite('gswSeir')} and the 35% planned for weekday peak events at Chase Center ${cite('gswTmp')}, for which no observed share has been published${evConst ? ` (constants ${evConst})` : ''}. Attendees from San Mateo and Santa Clara counties have one more transit constant${evSouth != null ? ` (${fx(evSouth, 2)})` : ''}, fitted to Caltrain's extra riders on Giants home weekdays: ${int(GC.weekdayHome)} systemwide against ${int(GC.weekdayAway)} on weekdays when the Giants were away in fiscal 2026 ${cite('caltrainRidership')}. Extra event-day service, the free Muni ride with a Chase Center ticket, and weekend events are not represented.</p>
<p>Ridership also changes for reasons outside the network: how often people go to their workplaces, how many people live and work in the city, how many visitors come, and what driving and transit cost. Each of these is an explicit input to a run, a <i>condition</i>, with today's value the one in July and August 2026 at which the model was calibrated (${tab('conditions')}); with every condition at today's value a run is the base run. Each acts where demand is generated: attendance and commute days scale the work tours of ${eq('commute')}, the share working from home scales ${math('\\omega_o')}, employed residents ${math('W_o')}, jobs the in-commuters, population residents' other tours, and the visitor conditions their generators. The price of gasoline moves driving's cost per mile: of the ${money(AUTO_COST_PER_MILE, 3)} of ${math('c_m')}, ${money(AUTO_NONFUEL_PER_MILE, 3)} is maintenance, repair, and tires ${cite('aaaCosts')}, and the rest is fuel, which moves in proportion to the price ${cite('eiaGas')}. Muni's fare multiplies its fares, cable cars included, and the Clipper discount replaces the ${money(CLIPPER_TRANSFER_DISCOUNT)} of ${sec('fares')}, applied either to any operator after another or, as before December 2025, only on boarding Muni. Service levels are not a condition, since they are the network itself. Car ownership, homes, workplaces, and the timing of travel stay fixed.</p>
${table(
  'conditions',
  'Conditions outside the network: today’s values (July–August 2026) and their sources.',
  ['Condition', 'Today', 'Source of today’s value'],
  CONDITIONS.map((c) => [c.label, c.unit === 'rel' ? '100%' : c.unit === 'usd' ? money(c.today) : c.unit === 'days' ? `${fx(c.today, 2)} a week` : pc(c.today, 1), c.basis]),
  { numeric: [1], wide: true, notes: `Sources: ${cite('kastle')}; ${cite('acs')}; ${cite('bats2023t45')}; ${cite('blsLaus')}; ${cite('blsQcew')}; ${cite('dofE1')}; ${cite('cityScorecard')}; ${cite('sfoStats')}; ${cite('eiaGas')}; ${cite('aaaCosts')}; ${cite('fares')}; ${cite('clipper2')}; ${cite('clipperMigration')}.` },
)}
`)}

${abmSection()}

${section('iteration', 'Iteration and convergence', `
<p>A model pass computes the transit skims for the four periods with the current crowding factors, then demand, then assignment for the four periods. After the first pass, each pass's crowding factors are averaged with the previous pass's, with equal weights. The boarding availabilities change more steeply with the loads, so they are averaged by the method of successive averages: the ${math('k')}th pass's value enters with weight ${math('1/k')}${CAP?.settleConvergence?.length ? `. Boardings at each line's stops changed by ${list(CAP.settleConvergence.map((c) => pc(c, 1)))} of the total from one pass to the next while the base run settled` : ''}. The base run of today's network is made in two steps: four passes from empty vehicles to settle the crowding and the availabilities, then one further pass from that crowding, which is the run saved and shown in the application. A scenario run starts from the base run's crowding in the same way, so a scenario with no changes reproduces the base. These runs do not reach a strict equilibrium between crowding and demand (${sec('limitations')}). Roads close a second loop: with traffic feedback, the road assignment's change in traffic enters the driving times and the running times of buses in mixed traffic, transit paths are found again, and demand chooses once more (${sec('roads')}). The calibration and today's base run are made without that feedback. Which loops a scenario run makes depends on its run mode (${sec('runmodes')}).</p>
`)}

${runModes()}

${weekendModel()}
`)}`;
}
